module.exports = [

/* ── Item 1 ── */
{id:"DEMO-001", t:"single", cn:"MOC", sys:"REPI", topic:"Prioritization · intrapartum", d:2, b:0.55, cj:"prioritize", tags:["priority"],
 stem:"The charge nurse has received a change-of-shift report on four clients in labor. The charge nurse should ask a staff member to first see the client in the",
 opts:["first stage of labor who has an oral temperature of 99.7° F (37.6° C)","first stage of labor whose contractions are occurring every 30 seconds","second stage of labor who has respirations of 26/min","second stage of labor whose contractions are lasting for 60 seconds"],
 ans:1,
 rat:{c:"Contractions every 30 seconds in the first stage of labor is tachysystole — the uterus never relaxes, which robs the fetus of oxygen and can rupture the uterus. This client needs assessment before the others.",
 o:["A low-grade temperature in the first stage of labor requires monitoring and hydration, but it is not the most urgent finding.",
 "Correct — contraction frequency of every 30 seconds means virtually no rest between contractions: assess this client first.",
 "A respiratory rate of 26/min during the work of the second stage is common and expected.",
 "Contractions lasting 60 seconds in the second stage (pushing) stage are effective and expected."],
 s:"Rank labor emergencies by uteroplacental threat: tachysystole > fever > expected second-stage findings. Frequency matters more than duration."},
 ref:"Demo practice set · item 1"},

/* ── Item 2 ── */
{id:"DEMO-002", t:"single", cn:"SIC", sys:"INF", topic:"Isolation precautions · varicella", d:1, b:-0.3, cj:"act", tags:["safety","infection-control"],
 stem:"The nurse is observing a staff member caring for a client who has chickenpox. Which of the following actions by the staff member would require the nurse to intervene?",
 opts:["placing the client in a private room with monitored negative air pressure","placing a box of disposable face shields outside the client’s room","placing an alcohol-based hand rub in the client’s room for hand hygiene","placing a surgical mask on the client during transport out of the client’s room"],
 ans:1,
 rat:{c:"Chickenpox (varicella) spreads by airborne droplet nuclei and direct contact with lesions. Staff need an N95 respirator (plus gown and gloves) — face shields alone imply eye/face protection is substituting for respiratory protection, so the nurse must intervene.",
 o:["Correct action — varicella requires an airborne infection isolation room (negative pressure).",
 "Requires intervention — a face shield protects the eyes/mucous membranes only; it does not filter inhaled airborne particles. Staff must wear an N95 respirator.",
 "Correct action — alcohol-based hand rub supports hand hygiene on entry and exit.",
 "Correct action — masking the client during transport helps contain airborne spread."],
 s:"For airborne diseases (varicella, TB, measles) think N95 + negative pressure for staff; a surgical mask on the client for transport."},
 ref:"Demo practice set · item 2"},

/* ── Item 3 ── */
{id:"DEMO-003", t:"multi", cn:"PAA", sys:"CV", topic:"Dysrhythmias · symptomatic bradycardia", d:2, b:0.6, cj:"act", tags:["priority","dysrhythmia"],
 stem:"The nurse is caring for a client who reports feeling faint and is experiencing the cardiac rhythm shown on the electrocardiogram (ECG) strip: a slow, regular rhythm at 38/min with one P wave for every QRS complex and no ectopic beats. Which of the following actions would be appropriate for the nurse to take? Select all that apply.",
 opts:["Administer the client’s prescribed beta blocker.","Prepare for transcutaneous pacing.","Instruct the client to perform the Valsalva maneuver.","Begin chest compressions.","Assess the client for angina."],
 ans:[1,4],
 rat:{c:"This is symptomatic sinus bradycardia (rate 38/min with faintness). Appropriate actions: prepare for transcutaneous pacing if rate/support fails to perfuse, and assess for angina caused by the low cardiac output. Anything that slows the heart further, or arrest interventions for a client with a pulse, are wrong.",
 o:["A beta blocker would further slow the rate — contraindicated in symptomatic bradycardia.",
 "Correct — symptomatic bradycardia is paced: prepare transcutaneous pacing pads while awaiting orders (atropine is often first-line medication).",
 "The Valsalva maneuver increases vagal tone and would slow the rate even more.",
 "Chest compressions are for pulseless arrest; this client has a perfusing rhythm and is symptomatic, not in arrest.",
 "Correct — cardiac output is low; assess for chest pain/angina as well as hypotension and altered mentation."],
 s:"Symptomatic bradycardia = prepare to pace + assess perfusion (angina, BP, mentation). Never give rate-slowing drugs or vagal maneuvers."},
 ref:"Demo practice set · item 3 (rhythm described in stem; image omitted)"},

/* ── Item 4 ── */
{id:"DEMO-004", t:"single", cn:"PSY", sys:"NEURO", topic:"Alzheimer’s disease · care planning", d:1, b:-0.2, cj:"generate", tags:["neuro","intervention"],
 stem:"The nurse is planning care for a client with moderate Alzheimer’s disease (AD). Which of the following interventions should the nurse include in the client’s plan of care?",
 opts:["Encourage the client to reminisce about happy memories.","Confront the client when inappropriate or agitated behaviors occur.","Administer to the client the cholinesterase inhibitor to reverse the course of AD.","Provide the client with information about activity choices in the morning so the client can make plans for the day."],
 ans:0,
 rat:{c:"Reminiscing about long-term (stored) memories is therapeutic in moderate AD — long-term memory outlasts recent memory and validating it supports dignity and orientation.",
 o:["Correct — reminiscence uses preserved long-term memory and promotes a sense of identity and well-being.",
 "Confrontation increases agitation and does not change behavior; use calm redirection instead.",
 "Cholinesterase inhibitors may temporarily stabilize or modestly improve symptoms; they do not reverse the disease.",
 "Planning a full day of choices exceeds moderate AD decision-making capacity — offer simple, limited choices instead."],
 s:"Moderate AD rules: validate and reminisce, redirect instead of confront, simple choices — and never promise a drug “reverses” the disease."},
 ref:"Demo practice set · item 4"},

/* ── Item 5 ── */
{id:"DEMO-005", t:"single", cn:"BCC", sys:"MSK", topic:"Assistive devices · crutches", d:1, b:-0.25, cj:"generate", tags:["safety","teaching","mobility"],
 stem:"The nurse is teaching a client how to ambulate using crutches. Which of the following information should the nurse include?",
 opts:["“Use your hands and arms to support your body weight.”","“Wear slippers when ambulating with the crutches in your home.”","“Maintain the crutches 12 in (30 cm) in front of your feet while standing.”","“Adjust the hand grips of the crutches so that your elbows are fully extended.”"],
 ans:0,
 rat:{c:"Weight is borne through the hands and arms on the hand grips — never through the axillae, which can crush the brachial plexus (crutch palsy).",
 o:["Correct — support body weight with the hands and arms; the axillary bars must stay 2–3 fingerbreadths off the axilla.",
 "Sturdy, non-slip shoes are required; slippers increase fall risk.",
 "The crutch tips are held about 6 in (15 cm) lateral to and in front of the feet, not 12 in.",
 "Elbows should be flexed about 20–30 degrees when gripping — full extension means the crutches are too long."],
 s:"Crutch ABCs: weight on HANDS (never armpits), elbows flexed 20–30°, tips 6 in out, sturdy shoes."},
 ref:"Demo practice set · item 5"},

/* ── Item 6 ── */
{id:"DEMO-006", t:"single", cn:"RRP", sys:"NEURO", topic:"Multiple sclerosis · self-care", d:2, b:0.45, cj:"evaluate", tags:["teaching","neuro"],
 stem:"The nurse has taught a client with multiple sclerosis (MS). Which of the following statements by the client would indicate a correct understanding of the teaching?",
 opts:["“I will complete all of my household chores in the morning when I am well rested.”","“I have learned how to massage my bladder to help empty my bladder completely.”","“I will take a hot bath in the evening to help me relax if I have had a stressful day at work.”","“I should expect the blurred vision to resolve after I have received medications for several weeks.”"],
 ans:1,
 rat:{c:"Neurogenic bladder in MS commonly causes incomplete emptying; techniques such as Credé (bladder) massage — along with timed voiding and intermittent self-catheterization — help achieve complete emptying and prevent infection.",
 o:["Bunching every activity into the morning causes fatigue overload; energy conservation means spreading tasks with rest periods.",
 "Correct — applying manual pressure over the lower abdomen can help empty a flaccid neurogenic bladder (as taught by the care team).",
 "Heat worsens MS symptoms (Uhthoff phenomenon) — hot baths should be avoided; lukewarm baths are suggested instead.",
 "Blurred vision in MS fluctuates with relapses and remissions; disease-modifying drugs do not promise vision recovery in weeks."],
 s:"Three MS traps: heat bad, fatigue managed by pacing (not pushing), and bladder techniques promote complete emptying."},
 ref:"Demo practice set · item 6"},

/* ── Item 13 ── */
{id:"DEMO-013", t:"single", cn:"PAA", sys:"RESP", topic:"Mechanical ventilation · complications", d:1, b:-0.2, cj:"evaluate", tags:["respiratory","evaluation"],
 stem:"The nurse has attended a staff education program about caring for clients who are receiving positive pressure mechanical ventilation. Which of the following statements by the nurse would indicate a correct understanding of the teaching?",
 opts:["“Clients should avoid range-of-motion (ROM) exercises until weaned from ventilation.”","“Clients may develop stress ulcers and gastrointestinal bleeding.”","“Clients will be chemically paralyzed to improve oxygenation.”","“Clients will experience diuresis and polyuria.”"],
 ans:1,
 rat:{c:"Positive pressure ventilation decreases splanchnic and gastric mucosal blood flow and raises gastric pH exposure — stress ulcers with GI bleeding are a recognized complication (hence stress-ulcer prophylaxis).",
 o:["Passive and active ROM should continue while ventilated to prevent contractures and DVT.",
 "Correct — stress ulcers and GI bleeding are known complications of positive pressure ventilation.",
 "Chemical paralysis is used only for specific indications (severe dyssynchrony, ventilation compromise), not routinely for oxygenation.",
 "Positive pressure ventilation more often DECREASES renal perfension and urine output (and causes fluid retention via ADH), rather than causing diuresis."],
 s:"Positive pressure side effects to remember: ↓ cardiac output/renal perfusion, fluid retention, stress ulcers, barotrauma, VAP."},
 ref:"Demo practice set · item 13"},

/* ── Item 14 ── */
{id:"DEMO-014", t:"single", cn:"MOC", sys:"INF", topic:"Assignment · interunit transfer", d:2, b:0.5, cj:"generate", tags:["delegation","priority"],
 stem:"The charge nurse must transfer a female client from the medical-surgical unit to the maternity unit to make a bed available. It would be most appropriate for the nurse to transfer the client who is",
 opts:["28 years old, had a right mastectomy and has a closed-wound drainage system","49 years old, has diabetes mellitus (type 2) and has begun receiving insulin","56 years old, has hepatitis C (HCV) and has been afebrile for 24 hours","70 years old, has a fractured left tibia and had an external fixation device applied 48 hours ago"],
 ans:0,
 rat:{c:"Send the most stable, predictable client with routine care needs. A postoperative mastectomy client with a closed-wound drainage system is stable and her care (drain management, arm exercises) is standardized — the least acute of the four.",
 o:["Correct — stable postoperative course with routine, standardized drain care; lowest risk on a maternity unit.",
 "New-onset insulin requires close glucose monitoring and teaching — not routine for maternity staff.",
 "Afebrile for only 24 hours after infection means still on the edge of instability; also requires ongoing assessment.",
 "An external fixation device needs orthopedic-focused neurovascular assessment and pin-site care."],
 s:"Interunit transfers: pick stable + predictable + low-acuity. New treatments, fresh infections, and device-heavy care stay on the specialty unit."},
 ref:"Demo practice set · item 14"},

/* ── Item 15 ── */
{id:"DEMO-015", t:"single", cn:"MOC", sys:"RESP", topic:"Prioritization · respiratory distress", d:2, b:0.5, cj:"prioritize", tags:["priority","assessment"],
 stem:"The nurse has been made aware of the following client situations. The nurse should first assess the client with",
 opts:["heart failure who has a productive cough and is anxious","regional enteritis (Crohn’s disease) who is reporting cramping abdominal pain and diarrhea","idiopathic thrombocytopenic purpura (ITP) who has petechiae on the trunk and is reporting heavy menses","chronic obstructive pulmonary disease (COPD) who has dyspnea with exertion and is using accessory muscles to breathe"],
 ans:3,
 rat:{c:"Using accessory muscles with dyspnea signals escalating respiratory distress — an airway/breathing emergency. ABCs outrank bleeding risk, chronic GI symptoms, and anxiety.",
 o:["A productive cough with anxiety in heart failure needs prompt assessment, but airway compromise is not evident.",
 "Cramping pain and diarrhea are expected Crohn’s flares — chronic and non-emergent.",
 "Petechiae with heavy menses in ITP indicates falling platelets — important, but breathing comes first.",
 "Correct — accessory muscle use means the client is working to breathe: assess first, anticipate oxygen and ABGs."],
 s:"When one option describes increased work of breathing, that is the ABC winner — every other choice is chronic or stable by comparison."},
 ref:"Demo practice set · item 15"},

/* ── Item 16 ── */
{id:"DEMO-016", t:"single", cn:"MOC", sys:"CV", topic:"Delegation · UAP scope", d:1, b:-0.35, cj:"generate", tags:["delegation"],
 stem:"The nurse and unlicensed assistive personnel (UAP) are caring for assigned clients. Which of the following tasks would be appropriate for the nurse to assign to UAP?",
 opts:["assisting a client with atrial fibrillation to shower","checking the ability of a client to swallow water after a transesophageal echocardiogram (TEE)","observing while a client with dysphagia begins a thickened liquid diet","transporting a client with respiratory distress to the radiology department for a chest radiograph"],
 ans:0,
 rat:{c:"UAP may perform routine, standardized care for stable clients — assisting a stable client to shower fits. Anything involving swallowing assessment, new diet trials, or an unstable client stays with the nurse.",
 o:["Correct — shower assistance for a stable client is a routine activity of daily living within the UAP scope.",
 "Swallow assessment after sedation/procedure (TEE) is a nursing assessment — the RN checks gag/swallow before oral intake.",
 "A client with dysphagia starting thickened liquids requires nursing observation — aspiration risk.",
 "A client in respiratory distress should not travel off the unit except with a nurse; UAP transport is inappropriate."],
 s:"UAP = stable client + routine task + no assessment, no teaching, no judgment. Meals and airways are nurse territory."},
 ref:"Demo practice set · item 16"},

/* ── Item 17 ── */
{id:"DEMO-017", t:"single", cn:"HPM", sys:"GI", topic:"Infant nutrition", d:2, b:0.4, cj:"recognize", tags:["pediatrics","nutrition"],
 stem:"The nurse has taken a nutritional history from parents of clients. It would be a priority for the nurse to follow up with the",
 opts:["5-month-old client whose only source of nutrition is 5 formula feedings daily","7-month-old client who eats several crackers as finger food","9-month-old client whose typical daily diet includes 10 bottles of 2% milk, 1 cup of apple juice, and 3 servings of infant cereal","1-year-old client whose typical food intake includes 4 breast-feedings and 3 servings of cooked vegetables, pears, or sliced cheese"],
 ans:2,
 rat:{c:"Ten bottles of 2% milk daily is the classic setup for “milk anemia” (iron deficiency) in late infancy — excess milk displaces iron-rich foods, and low-fat milk is not recommended before age 2. This diet also lacks protein variety and solids progression.",
 o:["Five formula feedings at 5 months is appropriate — formula (or breast milk) remains the primary nutrition through 12 months.",
 "Crackers as finger food at 7 months are developmentally appropriate alongside formula.",
 "Correct — 10 bottles of 2% milk plus juice and cereal means no iron- or protein-rich foods; follow up on this diet.",
 "A 1-year-old with breast-feeding plus varied table foods is eating well."],
 s:"Red flags in infant diets: excess cow’s milk (<16–24 oz/day), low-fat milk before age 2, juice overload, or a diet missing iron-rich solids after 6 months."},
 ref:"Demo practice set · item 17"},

/* ── Item 18 ── */
{id:"DEMO-018", t:"single", cn:"MOC", sys:"RESP", topic:"Prioritization · postoperative pulmonary", d:3, b:1.0, cj:"prioritize", tags:["priority","respiratory"],
 stem:"The nurse has become aware of the following client situations. The nurse should first assess the client",
 opts:["who had a right pneumonectomy 24 hours ago and is in the high-Fowler’s position while lying on the right side","with chronic obstructive pulmonary disease (COPD) who is using pursed-lip breathing and reporting hemoptysis","who had a wedge resection of the left lung 24 hours ago and is sitting in the high-Fowler’s position","with heart failure who has a productive cough and is restless"],
 ans:0,
 rat:{c:"After a pneumonectomy the pleural space is empty — positioning on the operative side can shift the mediastinum and compress the remaining lung (and the heart), a life-threatening event. Lying on the right (operative) side after a right pneumonectomy demands immediate assessment.",
 o:["Correct — avoid the operative side after pneumonectomy; this position risks mediastinal shift. Assess this client now.",
 "Pursed-lip breathing is a taught COPD technique; new hemoptysis needs evaluation but is not the immediate threat.",
 "High-Fowler’s after a wedge resection is appropriate and expected.",
 "A productive cough with restlessness in heart failure requires prompt assessment, but no positional emergency is present."],
 s:"Pneumonectomy ≠ lobectomy: never position on the operative side (mediastinal shift). Favor the operative side only after lobectomy/wedge to promote drainage."},
 ref:"Demo practice set · item 18"},

/* ── Item 19 ── */
{id:"DEMO-019", t:"single", cn:"RRP", sys:"NEURO", topic:"Head injury · pediatric monitoring", d:2, b:0.5, cj:"evaluate", tags:["pediatrics","neuro","assessment"],
 stem:"The nurse is caring for a 3-year-old client with a cerebral concussion who is being observed overnight in the pediatric unit. Which of the following observations would be most significant for the nurse to report to the oncoming shift?",
 opts:["The client has a blood pressure of 94/58 mm Hg and an apical pulse of 90.","The client is sleeping but is easily aroused.","The client’s pupils are equal and reactive to light.","The client has an axillary temperature of 99.0° F (37.2° C) and respirations of 24."],
 ans:3,
 rat:{c:"A low-grade fever with a respiratory rate at the top of the toddler range is the only deviation here — after a head injury it can signal a developing complication (or superimposed illness) that the next shift must trend. The other findings are expected post-concussion values for a 3-year-old.",
 o:["BP 94/58 with apical pulse 90 is within normal range for a toddler.",
 "Sleeping but easily arousable is an expected concussion pattern — wake frequently and confirm arousability, which is intact.",
 "Pupils equal and reactive is a normal neuro finding.",
 "Correct — an axillary temperature of 99.0° F (≈ 100° F orally) with respirations of 24 is the abnormal trend to hand off and monitor."],
 s:"Pediatric vitals by age: toddler HR 80–120, RR 20–30, SBP ≈ 90–100. Sleep is allowed after concussion if the child arouses easily — trend the temperature instead."},
 ref:"Demo practice set · item 19"},

/* ── Item 20 ── */
{id:"DEMO-020", t:"single", cn:"MOC", sys:"NEURO", topic:"Prioritization · same-day surgery", d:2, b:0.55, cj:"prioritize", tags:["priority","postoperative"],
 stem:"The nurse in the same-day surgical center has received a change-of-shift report on the following clients. The nurse should first see the client who had",
 opts:["closed reduction of a fractured tibia with cast application 1 hour ago and is reporting that the casted leg feels hot","extraction of a cataract lens 2 hours ago and is reporting nausea","an arthroscopy of the right knee 3 hours ago and is reporting knee pain rated as 4 on a scale of 0 (no pain) to 10 (severe pain)","a laparoscopic cholecystectomy 4 hours ago and is reporting right shoulder pain"],
 ans:1,
 rat:{c:"Nausea, vomiting, or coughing after cataract surgery raises intraocular pressure and can disrupt the surgical site — treat it first. A cast feeling hot is expected while plaster cures, moderate knee pain and referred shoulder pain (CO2) are routine.",
 o:["A freshly applied plaster cast warms as it sets — “feels hot” alone is expected; assess circulation separately.",
 "Correct — vomiting/retching after eye surgery spikes IOP and risks site damage: see this client first for antiemetic treatment.",
 "Pain of 4/10 after arthroscopy is expected and non-urgent.",
 "Right shoulder pain after laparoscopy is referred irritation from CO2 insufflation — common and self-limiting."],
 s:"Same-day surgery triage: anything that threatens the surgical result (IOP after eye surgery) beats expected postop discomforts (cast warmth, gas pain)."},
 ref:"Demo practice set · item 20"},

/* ── Item 21 ── */
{id:"DEMO-021", t:"single", cn:"RRP", sys:"NEURO", topic:"Multiple sclerosis · ataxia", d:1, b:-0.15, cj:"generate", tags:["neuro","referral"],
 stem:"The nurse is planning care for a client with multiple sclerosis (MS) who has ataxia. Which of the following interventions should the nurse include in the client’s plan of care?",
 opts:["Add thickener to thin liquids for the client.","Obtain a referral to a physical therapist for the client.","Face the client directly when speaking with the client.","Provide a board with pictures to help the client communicate needs."],
 ans:1,
 rat:{c:"Ataxia is impaired coordination and balance — physical therapy (gait training, balance exercise, assistive devices) is the targeted intervention and reduces fall risk.",
 o:["Thickened liquids address dysphagia (seen in advanced MS), not ataxia.",
 "Correct — PT addresses balance, coordination, safety, and adaptive equipment for ataxia.",
 "Facing the client directly helps when the problem is communication or visual field loss, not coordination.",
 "A picture board supports expressive aphasia or severe dysarthria, not ataxia."],
 s:"Match the intervention to the deficit: ataxia → PT/safety; dysphagia → thickener/swallow eval; aphasia → communication board; hearing/vision → face the client."},
 ref:"Demo practice set · item 21"},

/* ── Item 22 ── */
{id:"DEMO-022", t:"single", cn:"MOC", sys:"INF", topic:"Prioritization · home health", d:2, b:0.5, cj:"prioritize", tags:["priority","oncology"],
 stem:"The home-health nurse is assigned to visit the following clients who live within 3 miles (4.8 km) of one another. The nurse should first visit the client with",
 opts:["breast cancer who had a mastectomy 2 days ago and has had 25 mL of drainage from the closed-wound drainage system in the past 12 hours","lung cancer who received a dose of chemotherapy 2 weeks ago and has a temperature of 101.1° F (38.4° C)","chronic obstructive pulmonary disease (COPD) who is reporting expectorating large amounts of thick, yellow mucus","diabetes mellitus (type 1) who had a right below-the-knee amputation (BKA) and is reporting having right toe pain"],
 ans:1,
 rat:{c:"Fever of 101.1° F two weeks after chemotherapy means possible neutropenic sepsis until proven otherwise — a same-hour emergency. The others are expected findings or non-urgent concerns.",
 o:["25 mL of drainage in 12 hours after mastectomy is within expected range for a surgical drain.",
 "Correct — chemotherapy-induced neutropenia + fever is an oncologic emergency; visit first and expect the febrile-neutropenia protocol to begin.",
 "A change in sputum in COPD needs evaluation within the day but is not immediately life-threatening.",
 "Phantom limb pain after BKA is common and treated on schedule — and the toes are amputated, so pain is neurologic, not perfusion."],
 s:"Any fever after chemo = neutropenic emergency. Expected drain output, sputum change, and phantom pain wait."},
 ref:"Demo practice set · item 22"},

/* ── Item 23 ── */
{id:"DEMO-023", t:"single", cn:"MOC", sys:"MSK", topic:"Prioritization · postoperative embolism", d:2, b:0.6, cj:"prioritize", tags:["priority","assessment"],
 stem:"The nurse has become aware of the following client situations. The nurse should first assess the client",
 opts:["who had a total abdominal hysterectomy (TAH) 1 day ago and is unable to void 7 hours after the indwelling urethral catheter was removed","who had a total knee replacement 24 hours ago, is restless, and has a petechial rash on the chest","with bacterial pneumonia who has bronchial breath sounds auscultated between the scapulae and a temperature of 103.3° F (39.6° C)","with hepatic cirrhosis who has an elevated aspartate aminotransferase (AST) level and respirations of 24"],
 ans:1,
 rat:{c:"Restlessness plus a petechial rash on the chest 24 hours after knee surgery is fat embolism syndrome — respiratory failure, arming rapidly. It outranks urinary retention, febrile pneumonia, and stable cirrhosis labs.",
 o:["Inability to void 7 hours after catheter removal needs intervention (bladder scan, protocol) but is not life-threatening.",
 "Correct — petechiae (chest/axilla/neck), restlessness, and recent long-bone/joint surgery = fat embolism: assess oxygen saturation and mental status immediately.",
 "A fever with consolidated breath sounds in pneumonia is serious but expected and already diagnosed.",
 "An elevated AST with mild tachypnea in known cirrhosis is chronic and non-urgent."],
 s:"Fat embolism triad after orthopedic surgery: hypoxemia/restlessness, petechial rash (chest, axillae, neck), thrombocytopenia. ABCs + sudden change wins."},
 ref:"Demo practice set · item 23"},

/* ── Item 24 ── */
{id:"DEMO-024", t:"single", cn:"SIC", sys:"INF", topic:"Isolation precautions · pertussis", d:1, b:-0.3, cj:"generate", tags:["infection-control","pediatrics"],
 stem:"The nurse is planning care for a pediatric client being admitted with pertussis. Which of the following interventions should the nurse include in the client’s plan of care?",
 opts:["Keep the client NPO.","Place a dehumidifier in the client’s room.","Encourage the client to ambulate frequently.","Implement droplet precautions."],
 ans:3,
 rat:{c:"Pertussis spreads by large respiratory droplets — droplet precautions (surgical mask within 3–6 feet, single room preferred) are the required intervention.",
 o:["Nutrition and fluids are supported in small frequent feeds; NPO is not indicated.",
 "A cool-mist humidifier may soothe airway irritation — a dehumidifier dries the air and is not indicated.",
 "Rest conserves energy during paroxysmal coughing; frequent ambulation is not the priority.",
 "Correct — droplet precautions with a surgical mask protect staff and other children."],
 s:"Droplet diseases (pertussis, influenza, meningococcus, rubella, mumps): surgical mask + private room. No N95, no negative pressure needed."},
 ref:"Demo practice set · item 24"},

/* ── Item 25 ── */
{id:"DEMO-025", t:"single", cn:"SIC", sys:"INF", topic:"Infection control · precautions matching", d:2, b:0.5, cj:"evaluate", tags:["infection-control"],
 stem:"The nurse has attended a staff education program about infection control precautions. It would indicate a correct understanding of the teaching if the nurse is observed",
 opts:["wearing a particulate respirator mask (N95) when entering the room of a client with Haemophilus influenzae pneumonia","placing a client with streptococcal pneumonia in a room with a client who has respiratory syncytial virus (RSV)","wearing a protective gown when entering the room of a client with Escherichia coli O157:H7 who is incontinent","placing a client with pediculosis capitis (head lice) in a room with a client who has scabies"],
 ans:2,
 rat:{c:"E. coli O157:H7 is spread by the fecal-oral route, and an incontinent client contaminates the environment — gown (and gloves) on entry is correct contact precaution practice.",
 o:["H. influenzae pneumonia requires DROPLET precautions — a surgical mask, not an N95.",
 "Roommates must be on the same precautions and ideally share no pathogens — streptococcal pneumonia (droplet) + RSV (contact/droplet) is an unsafe pairing.",
 "Correct — contact precautions for a diarrheal/incontinent client: gown and gloves on entry.",
 "Head lice (contact) and scabies (contact) are different infestations — do not co-locate clients with communicable conditions."],
 s:"Match PPE to the route: airborne = N95/negative pressure; droplet = surgical mask; contact = gown + gloves. Never mix communicable roommates."},
 ref:"Demo practice set · item 25"},

/* ── Item 26 ── */
{id:"DEMO-026", t:"multi", cn:"SIC", sys:"MSK", topic:"Fall prevention · extrinsic hazards", d:1, b:-0.35, cj:"recognize", tags:["safety","older-adults"],
 stem:"The nurse is assessing an older adult client who is scheduled for discharge and is at risk for falls. Which of the following are extrinsic risk factors for falling? Select all that apply.",
 opts:["uneven stairs","throw rugs","hemiparesis","dim lighting","confusion"],
 ans:[0,1,3],
 rat:{c:"Extrinsic (environmental) risk factors come from the surroundings — uneven stairs, throw rugs, and dim lighting. Hemiparesis and confusion are intrinsic factors within the client.",
 o:["Correct — environmental hazard: fix or avoid uneven stairs.",
 "Correct — throw rugs are a classic trip hazard to remove before discharge.",
 "Hemiparesis (muscle weakness) is an INTRINSIC factor — part of the client, not the environment.",
 "Correct — poor lighting is an extrinsic hazard; add nightlights and bright bulbs.",
 "Confusion is an INTRINSIC (client-related) cognitive risk factor."],
 s:"Extrinsic = things you can remove from the home (rugs, cords, lighting, stairs). Intrinsic = things true of the client (weakness, gait, cognition, medications)."},
 ref:"Demo practice set · item 26"},

/* ── Item 27 ── */
{id:"DEMO-027", t:"multi", cn:"SIC", sys:"INTG", topic:"Impetigo · infection control", d:1, b:-0.2, cj:"generate", tags:["infection-control","pediatrics"],
 stem:"The nurse is caring for a 3-year-old client with impetigo. Which of the following infection control precautions should the nurse implement? Select all that apply.",
 opts:["Wear a surgical mask when bathing the client.","Wear a protective gown when changing the client’s bed linens.","Keep the door to the client’s room closed.","Place a box of clean gloves outside the client’s door.","Place a surgical mask on the client during transport to other departments."],
 ans:[1,3],
 rat:{c:"Impetigo (Staphylococcus aureus / Streptococcus pyogenes) requires CONTACT precautions: gloves for care, gown when clothing will be soiled (linen changes), and dedicated PPE stocked at the door.",
 o:["Impetigo is not respiratory — a surgical mask is not part of contact precautions.",
 "Correct — gown when linens are likely contaminated with drainage.",
 "A closed door is an AIRBORNE precaution measure; contact precautions do not require it.",
 "Correct — gloves must be donned before entering; stocking them outside the door supports compliance.",
 "Masking the client addresses droplet/airborne spread — not indicated for impetigo."],
 s:"Impetigo = contact precautions: gloves always, gown for soiling, no mask, no closed-door rule. Transport requires covering lesions, not a mask."},
 ref:"Demo practice set · item 27"},

/* ── Item 28 ── */
{id:"DEMO-028", t:"single", cn:"SIC", sys:"INF", topic:"Tuberculosis · isolation", d:1, b:-0.25, cj:"evaluate", tags:["infection-control"],
 stem:"The nurse is evaluating a staff member’s care of a client with active pulmonary tuberculosis (TB). Which of the following actions by the staff member would indicate to the nurse an understanding of the principles of infection control for tuberculosis isolation?",
 opts:["instructing visitors to wash their hands before entering the client’s room","putting on a mask, gown, and gloves before entering the client’s room","placing tissues and a trash receptacle within the client’s reach","asking the client to put on a clean mask each time someone enters the room"],
 ans:2,
 rat:{c:"Giving the client tissues and a receptacle supports covering the mouth when coughing — an honest, effective TB control measure (source control) that staff can maintain.",
 o:["Hand hygiene matters, but visitors need RESPIRATORY protection (N95) before entering an airborne-precaution room — handwashing alone misses the point.",
 "Staff must wear an N95 RESPIRATOR for TB (airborne); a plain mask with gown and gloves does not filter droplet nuclei.",
 "Correct — tissues and a no-touch receptacle at the bedside support cough etiquette/source control.",
 "The client masks during TRANSPORT, not every time someone enters the room; the entrants wear the N95s."],
 s:"TB isolation toolkit: staff N95 + AIIR (negative pressure) + door closed; client covers coughs (tissues at hand) and masks only during transport."},
 ref:"Demo practice set · item 28"},

/* ── Item 29 ── */
{id:"DEMO-029", t:"single", cn:"SIC", sys:"INF", topic:"Rubeola · room assignment", d:1, b:-0.2, cj:"generate", tags:["infection-control","pediatrics"],
 stem:"The nurse in the pediatric unit is preparing to admit a client with rubeola (measles). The nurse should assign the client to a",
 opts:["private room at the end of the hallway","private room with monitored negative air pressure","room with a client who has chickenpox","room with a client who has atopic dermatitis (eczema)"],
 ans:1,
 rat:{c:"Measles is one of the most contagious airborne diseases — the client needs a private airborne infection isolation room (AIIR) with monitored negative pressure, with staff in N95 respirators.",
 o:["A private room alone does not prevent airborne spread; air must be controlled (negative pressure).",
 "Correct — airborne precautions: private room with monitored negative air pressure (AIIR) + N95 respirators.",
 "Never cohort a suspected measles client with chickenpox — both are airborne, and co-infection risk/confirmation issues make this inappropriate.",
 "A client with eczema has broken skin and infection vulnerability — not an appropriate roommate for a communicable airborne disease."],
 s:"Airborne club (measles, TB, varicella, disseminated zoster): negative-pressure private room + N95. A hallway-end room is not an AIIR."},
 ref:"Demo practice set · item 29"},

/* ── Item 30 ── */
{id:"DEMO-030", t:"single", cn:"SIC", sys:"INF", topic:"Infection control · monitoring practice", d:2, b:0.5, cj:"act", tags:["infection-control"],
 stem:"The charge nurse is observing the following client situations. It would require intervention if a",
 opts:["client with hepatitis B (HBV) is eating food brought into the facility by a visitor","visitor is sitting on the side of the bed of a client with acute pancreatitis","staff member is entering the room of a client with Haemophilus influenzae meningitis wearing a protective gown and gloves","family member of a client with mycoplasma pneumonia leaves the door to the client’s room open"],
 ans:2,
 rat:{c:"H. influenzae meningitis requires DROPLET precautions — the essential item is a surgical mask within 3–6 feet of the client. Gown and gloves without a mask misses the required protection, so the charge nurse must intervene.",
 o:["HBV spreads by blood/body fluids, not food sharing — eating visitor-brought food is acceptable.",
 "Sitting on the bed of a client with pancreatitis poses no transmission concern under standard precautions.",
 "Correct — droplet precautions demand a surgical mask; gown/gloves alone leave the staff member unprotected.",
 "Droplet spread travels short distances with close contact; a closed door is an airborne-precaution measure, so an open door with mycoplasma (droplet) is acceptable."],
 s:"For droplet diseases the make-or-break PPE is the surgical mask. Gowns/gloves answer the CONTACT question; closed doors answer the AIRBORNE question."},
 ref:"Demo practice set · item 30"},

/* ── Item 38 ── */
{id:"DEMO-038", t:"single", cn:"RRP", sys:"REN", topic:"Acute kidney injury · orders", d:1, b:-0.2, cj:"act", tags:["renal","safety"],
 stem:"The nurse is reviewing the orders of a client who has acute kidney injury. Which of the following orders should the nurse clarify?",
 opts:["computed tomography (CT) scan of the abdomen with intravenous contrast media","urine specimen for urinalysis","blood specimen for arterial blood gas (ABG)","referral to registered dietitian for parenteral nutrition evaluation"],
 ans:0,
 rat:{c:"IV contrast is nephrotoxic and can worsen acute kidney injury — the nurse must clarify this order before the client goes to radiology.",
 o:["Correct — iodinated IV contrast is contraindicated/hazardous in AKI; clarify with the provider (a non-contrast study may be possible).",
 "Urinalysis is a routine, harmless part of the AKI workup.",
 "ABGs are appropriate — AKI causes metabolic acidosis and hyperkalemia that ABGs help track.",
 "Dietitian referral for nutrition planning is standard supportive care in AKI."],
 s:"See “contrast” + “kidney” on an exam → clarify. Everything else listed is monitoring/supportive care."},
 ref:"Demo practice set · item 38"},

/* ── Item 39 ── */
{id:"DEMO-039", t:"single", cn:"SIC", sys:"PSYCH", topic:"Restraints · standards", d:1, b:-0.15, cj:"generate", tags:["safety","legal"],
 stem:"The nurse is planning a staff education program about caring for clients with restraints. Which of the following information should the nurse include?",
 opts:["“Restraints should be removed once during a shift to perform passive range-of-motion (ROM) exercises for the client.”","“Restraints should be secured to the side rails of the client’s bed for quick release.”","“Restraints require an order from the primary health care provider.”","“Restraints may be used p.r.n. for clients who are confused.”"],
 ans:2,
 rat:{c:"Restraints require a provider’s order (time-limited and renewed per policy), the least-restrictive method must be tried first, and use must be continually justified and documented.",
 o:["Release with ROM is required on a regular schedule (typically every 2 hours) — not merely once a shift.",
 "Securing ties to the side rail causes injury when the rail moves; ties anchor to the bed FRAME with a quick-release knot.",
 "Correct — a provider order is mandatory, along with ongoing monitoring and documentation.",
 "PRN restraint orders are prohibited — orders must be time-limited and reflect a specific behavior."],
 s:"Restraint rules: provider order (never PRN), least restrictive, secure to the bed frame, release/ROM q2h, monitor circulation q2h (non-violent) or q15min (violent)."},
 ref:"Demo practice set · item 39"},

/* ── Item 40 ── */
{id:"DEMO-040", t:"single", cn:"SIC", sys:"INF", topic:"Tuberculosis · plan of care", d:1, b:-0.25, cj:"generate", tags:["infection-control"],
 stem:"The nurse is caring for a client with active pulmonary tuberculosis (TB). Which of the following should the nurse include in the client’s plan of care?",
 opts:["placing the client in a private room with the door open","putting a surgical mask on the client during transport to the radiology department","instructing the primary caregivers to wear surgical masks when caring for the client","instituting the standards for droplet precautions while caring for the client"],
 ans:1,
 rat:{c:"Active pulmonary TB requires airborne precautions (AIIR with door closed, staff in N95 respirators); when the client must leave the room, the CLIENT wears a surgical mask to contain droplet nuclei.",
 o:["The AIIR door must stay CLOSED to maintain negative pressure.",
 "Correct — the client wears a surgical mask during transport to protect others.",
 "Caregivers need N95 respirators (fit-tested), not surgical masks — TB droplet nuclei are small enough to pass through a surgical mask.",
 "TB is AIRBORNE, not droplet — droplet precaution standards are insufficient."],
 s:"TB = airborne: negative-pressure room, door closed, N95 on staff, surgical mask on the client for transport."},
 ref:"Demo practice set · item 40"},

/* ── Item 41 ── */
{id:"DEMO-041", t:"single", cn:"HPM", sys:"INTG", topic:"Impetigo · home care teaching", d:1, b:-0.2, cj:"generate", tags:["teaching","pediatrics","infection-control"],
 stem:"The home-health nurse is teaching the parents of a 4-year-old client with impetigo. Which of the following information should the nurse include?",
 opts:["“Put a surgical mask on your child when around siblings.”","“Cleanse the lesions with a povidone-iodine solution daily.”","“Apply petroleum jelly to the lesions daily.”","“Instruct your child not to use the same towels as siblings.”"],
 ans:3,
 rat:{c:"Impetigo spreads by direct contact with lesions and contaminated shared items — separate towels (and linens) interrupt transmission at home.",
 o:["Impetigo is not respiratory — masking is pointless.",
 "Gentle cleansing with soap and water is recommended; povidone-iodine is not required and can irritate.",
 "Petroleum jelly alone does not treat the infection; antibiotic ointment (as prescribed) with crust care is the plan.",
 "Correct — no shared towels/washcloths; wash linens separately and practice hand hygiene after lesion contact."],
 s:"Home impetigo rules: wash hands, no sharing towels/linens, gentle soap-and-water cleansing, complete the prescribed topical/oral antibiotic."},
 ref:"Demo practice set · item 41"},

/* ── Item 42 ── */
{id:"DEMO-042", t:"single", cn:"SIC", sys:"INF", topic:"Bioterrorism · agent transmission", d:2, b:0.45, cj:"evaluate", tags:["infection-control","emergency"],
 stem:"The nurse has attended a staff education program about bioterrorism. Which of the following statements by the nurse would require follow-up?",
 opts:["“Botulism is transmitted by ingestion of contaminated canned foods.”","“Hemorrhagic fever is spread by direct contact with blood or body fluids.”","“Anthrax is spread through direct contact with the bacteria and its spores.”","“Bubonic plague is transmitted from person to person via airborne droplets.”"],
 ans:3,
 rat:{c:"Bubonic plague is transmitted by the bite of infected fleas (from rodents) — it is NOT spread person to person. Only PNEUMONIC plague spreads by airborne droplets, so this statement needs correction.",
 o:["Accurate — botulism toxin is ingested in improperly canned/anaerobic foods.",
 "Accurate — hemorrhagic fevers (e.g., Ebola) spread via blood and body fluid contact.",
 "Accurate — cutaneous anthrax follows contact with spores; inhalation anthrax follows inhaling them.",
 "Requires follow-up — bubonic plague comes from flea bites; person-to-person airborne spread describes pneumonic plague."],
 s:"Plague forms: bubonic = fleas/rodents; pneumonic = airborne droplets (the contagious one). Botulism = canned food; anthrax = spores; hemorrhagic fevers = body fluids."},
 ref:"Demo practice set · item 42"},

/* ── Item 43 ── */
{id:"DEMO-043", t:"single", cn:"RRP", sys:"RESP", topic:"Physical assessment · thoracic expansion", d:2, b:0.4, cj:"evaluate", tags:["assessment","respiratory"],
 stem:"The nurse observes a coworker who is assessing a client’s thoracic expansion. Which of the following would indicate that the coworker is using the correct assessment technique?",
 opts:["percussion from the apex of the scapula downward on each side","placement of the hands flat on the back with the thumbs at the level of the tenth ribs pointing to the spine, then asking the client to inhale","measurement of the anteroposterior diameter of the chest","placement of the palms at the level of the tenth ribs with thumbs pointing to the xiphoid process, then asking the client to inhale"],
 ans:1,
 rat:{c:"To assess thoracic expansion the examiner places both hands flat on the posterolateral chest at the level of the tenth ribs with the thumbs alongside the spine (pointing toward each other/vertebrae), then watches how far the thumbs separate symmetrically on inhalation.",
 o:["Percussion maps lung tissue/density — it does not measure expansion.",
 "Correct — thumbs at the level of the tenth ribs pointing toward the spine; observe symmetric separation on inhalation.",
 "AP diameter is inspection, not an expansion maneuver.",
 "Thumbs point toward the SPINE (vertebrae), not the xiphoid process."],
 s:"Thoracic expansion = flat hands posterolaterally at the 10th rib level, thumbs toward the spine, watch for symmetric separation on inhale."},
 ref:"Demo practice set · item 43"},

/* ── Item 44 ── */
{id:"DEMO-044", t:"single", cn:"HPM", sys:"REPI", topic:"Perimenopause · lifestyle", d:1, b:-0.4, cj:"generate", tags:["teaching"],
 stem:"The nurse at a health fair is talking with a client who is in perimenopause and is experiencing hot flashes. Which of the following lifestyle modifications would be appropriate for the nurse to recommend?",
 opts:["increasing fluid intake","exercising daily","decreasing sodium intake","wearing clothing in layers"],
 ans:3,
 rat:{c:"Dressing in layers lets the client shed clothing quickly when a hot flash strikes — the directly targeted lifestyle modification for vasomotor symptoms.",
 o:["Fluids are healthy generally but do not manage hot flashes.",
 "Daily exercise supports overall health and may modestly help, but it is not the specific measure for hot flashes.",
 "Sodium reduction targets blood pressure, not vasomotor symptoms.",
 "Correct — layered clothing is adjustable during sudden heat episodes; avoiding caffeine/spicy foods and keeping the environment cool also help."],
 s:"Match the modality to the symptom: hot flashes → layers, cool environment, trigger avoidance."},
 ref:"Demo practice set · item 44"},

/* ── Item 45 ── */
{id:"DEMO-045", t:"single", cn:"HPM", sys:"INF", topic:"Older adults · health promotion", d:1, b:-0.3, cj:"generate", tags:["teaching","older-adults"],
 stem:"The nurse in a community-based setting is teaching clients over 65 years of age about health promotion activities. Which of the following information should the nurse include?",
 opts:["“Purchase all of your prescribed medications at the same pharmacy.”","“Schedule an appointment for a vision screening every 3 years.”","“Participate in daily aerobic exercises for 60 minutes.”","“Increase your intake of fat-soluble vitamins.”"],
 ans:0,
 rat:{c:"One pharmacy for all prescriptions lets the pharmacist screen the whole medication list for interactions and duplications — a key safety practice for older adults on multiple drugs.",
 o:["Correct — a single pharmacy enables interaction checking across all prescribers.",
 "Older adults should have eye examinations ANNUALLY (glaucoma, macular degeneration), not every 3 years.",
 "Moderate activity most days (about 30 minutes) is the recommendation; 60 minutes of daily aerobic exercise is not required.",
 "Fat-soluble vitamins (A, D, E, K) can accumulate and reach toxic levels — supplementation is not routine advice."],
 s:"Older-adult health promotion: annual vision/health exams, one pharmacy, moderate exercise, immunizations (influenza, pneumococcal, zoster)."},
 ref:"Demo practice set · item 45"},

/* ── Item 46 ── */
{id:"DEMO-046", t:"single", cn:"HPM", sys:"HEME", topic:"Cancer risk · leukemia", d:2, b:0.5, cj:"analyze", tags:["oncology","assessment"],
 stem:"The nurse is screening clients for those at increased risk for developing a malignancy. At highest risk for developing leukemia is the client who",
 opts:["received more than 3 blood transfusions","has a magnetic resonance imaging (MRI) scan annually","has polycythemia vera and requires phlebotomy treatments","had colon cancer and received chemotherapy treatments"],
 ans:3,
 rat:{c:"Alkylating chemotherapy and other chemo agents are a known cause of therapy-related secondary leukemia (especially myeloid) — prior colon cancer treated with chemotherapy carries the highest leukemia risk listed.",
 o:["Transfusions do not cause leukemia (they carry infection/iron-load considerations, not malignancy).",
 "MRI uses magnetic fields, not ionizing radiation — no leukemia link.",
 "Polycythemia vera can rarely transform into leukemia, but the strongest, most tested risk here is prior chemotherapy.",
 "Correct — chemotherapy is an established leukemogen; survivors of chemo-treated cancers need long-term monitoring."],
 s:"Leukemia risk factors to memorize: prior chemo/radiation, benzene exposure, smoking, Down syndrome, myeloproliferative disorders, family history."},
 ref:"Demo practice set · item 46"},

/* ── Item 47 ── */
{id:"DEMO-047", t:"single", cn:"BCC", sys:"INF", topic:"Older adults · postoperative needs", d:1, b:-0.25, cj:"analyze", tags:["older-adults","postoperative"],
 stem:"The nurse is caring for an older adult client in the postoperative period. The nurse should know that this client, compared with younger clients in the postoperative period, will have an increased need for",
 opts:["oral hygiene","analgesics","high-calorie foods","early mobilization"],
 ans:0,
 rat:{c:"Older adults have reduced salivation and thicker secretions, and mouth dryness from fasting, oxygen, and anticholinergics — meticulous oral hygiene prevents mucosal breakdown, parotitis, and pneumonia.",
 o:["Correct — aging decreases saliva and mucous membrane integrity; older adults need MORE frequent, thorough oral care.",
 "Older adults often need LESS analgesic (slower metabolism/excretion, higher sensitivity) — with renal function in mind.",
 "Metabolic needs fall with age; high-calorie intake is not the answer (protein-adequate, balanced nutrition is).",
 "Early mobilization benefits every postoperative client — it is not an “increased need” unique to older adults."],
 s:"Older-adult postop differentiators: drier mucous membranes (↑ oral care), fragile skin, blunted fever, slower drug clearance."},
 ref:"Demo practice set · item 47"},

/* ── Item 48 ── */
{id:"DEMO-048", t:"multi", cn:"HPM", sys:"REN", topic:"Pediatric UTI prevention", d:1, b:-0.3, cj:"generate", tags:["pediatrics","teaching"],
 stem:"The nurse is planning a staff education program about the prevention of urinary tract infections (UTIs) in children. Which of the following information should the nurse include? Select all that apply.",
 opts:["“Teach the child to perform Kegel exercises.”","“Encourage the child to empty the bladder completely.”","“Encourage the child to maintain an adequate fluid intake.”","“Teach the child how to properly cleanse the perineal area.”","“Offer the child noncarbonated, decaffeinated beverage choices.”"],
 ans:[1,2,3,4],
 rat:{c:"UTI prevention in children rests on complete bladder emptying, good fluid intake (flushes the tract), proper perineal hygiene (wipe front to back in girls), and avoiding bladder irritants (caffeine, carbonation).",
 o:["Kegel exercises treat adult stress incontinence — not a pediatric UTI prevention measure.",
 "Correct — complete, unhurried voiding prevents urine stasis that breeds bacteria.",
 "Correct — adequate fluids dilute urine and increase flow.",
 "Correct — correct perineal cleansing (front to back) prevents perineal flora entering the urethra.",
 "Correct — caffeine and carbonated drinks irritate the bladder; offer noncarbonated, caffeine-free choices."],
 s:"Child UTI prevention = “empty it, flood it, clean it, don’t irritate it.” Kegels are an adult-incontinence tool."},
 ref:"Demo practice set · item 48"},

/* ── Item 49 ── */
{id:"DEMO-049", t:"single", cn:"PHA", sys:"HEME", topic:"Blood administration · pretransfusion", d:2, b:0.5, cj:"act", tags:["medication","transfusion","safety"],
 stem:"The nurse is preparing to administer a unit of packed red blood cells (PRBCs) to a client. Which of the following actions should the nurse take?",
 opts:["Assess the client’s recent urine output.","Prime a Y-tubing blood administration set with lactated Ringer’s solution.","Ensure that the client has a peripheral venous access device (VAD) that is 24-gauge or larger.","Verify with another nurse that the client’s room number is on both the blood product label and the client’s identification band."],
 ans:2,
 rat:{c:"Blood may infuse through at least a 24-gauge (ideally larger) peripheral catheter without hemolysis — verifying access size is the correct pretransfusion action. Only 0.9% sodium chloride is compatible with blood, and identification uses name/ID number, never the room number.",
 o:["Urine output is not a routine pretransfusion checkpoint (baseline vitals and ID checks are).",
 "Lactated Ringer’s causes hemolysis (calcium clumps with the anticoagulant) — prime with 0.9% saline only.",
 "Correct — a 24-gauge or larger VAD safely carries PRBCs; smaller gauges risk hemolysis.",
 "Room numbers are not client identifiers — two nurses verify the client’s NAME and ID number against the blood label."],
 s:"Transfusion setup rules: 0.9% NS only (never LR or D5W), 24-gauge or larger, two-RN ID check (name + ID, not room), baseline vitals, remain present for the first 15 minutes."},
 ref:"Demo practice set · item 49"},

/* ── Item 50 ── */
{id:"DEMO-050", t:"single", cn:"PSY", sys:"CV", topic:"Coping · post-MI", d:2, b:0.4, cj:"evaluate", tags:["psychosocial","evaluation"],
 stem:"The nurse is assessing the coping strategies of a client who had a myocardial infarction (MI) 3 days ago. Which of the following statements by the client would indicate ineffective coping?",
 opts:["“I know that stopping smoking will be difficult.”","“I plan to attend a cardiac rehabilitation support group.”","“I have trouble believing this has really happened to me.”","“I have let down my family because I will not be able to financially support them any longer.”"],
 ans:3,
 rat:{c:"A blanket declaration of total failure and inability to provide for the family signals hopelessness and negative self-appraisal — ineffective coping that warrants further assessment and support.",
 o:["Acknowledging that quitting smoking is hard is realistic and honest.",
 "Joining a support group is active, adaptive coping.",
 "Some initial disbelief is a common, normal acute reaction — monitor, but not the red flag here.",
 "Correct — global hopelessness (“I have let down my family… any longer”) is ineffective coping; assess for depression and suicidal ideation."],
 s:"Ineffective-coping markers: hopelessness, helplessness, worthlessness, catastrophizing. Normal acute reactions (disbelief, realistic concern) are not automatically pathologic."},
 ref:"Demo practice set · item 50"},

/* ── Item 51 ── */
{id:"DEMO-051", t:"single", cn:"PSY", sys:"INF", topic:"End-of-life · comfort care", d:1, b:-0.2, cj:"evaluate", tags:["palliative","teaching"],
 stem:"The hospice nurse has taught an in-home caregiver about comfort care for a client at the end of life. Which of the following statements by the caregiver would require follow-up?",
 opts:["“I have been applying petroleum jelly to keep the client’s lips moist.”","“I have been offering healthy foods frequently to keep up the client’s strength.”","“A blowing fan seems to be less anxiety-producing for the client than an oxygen mask.”","“Sitting upright seems to reduce the client’s noisy breathing more than lying down in the bed.”"],
 ans:1,
 rat:{c:"At the end of life, appetite falls naturally and forcing food causes discomfort — comfort care means offering (not pushing) food and drink. The other statements are appropriate comfort measures.",
 o:["Petroleum jelly for dry lips is appropriate mouth comfort care.",
 "Requires follow-up — pushing “healthy foods frequently” contradicts end-of-life comfort principles; offer small favorites without pressure.",
 "A fan for air hunger is an accepted comfort measure when a mask distresses the client.",
 "Upright positioning easing noisy breathing (death rattle) is appropriate."],
 s:"End-of-life teaching themes: feed for comfort not nutrition, manage air hunger (fan, position, atropine for secretions), keep lips moist, favor whatever calms the client."},
 ref:"Demo practice set · item 51"},

/* ── Item 52 ── */
{id:"DEMO-052", t:"multi", cn:"MOC", sys:"INF", topic:"Informed consent · validity", d:2, b:0.5, cj:"analyze", tags:["legal"],
 stem:"The nurse is witnessing the client’s signature on a consent form. Which of the following conditions should the nurse recognize must be met to ensure the consent is valid? Select all that apply.",
 opts:["The client gave consent voluntarily.","The client received adequate disclosure.","The consent form is witnessed by 2 health care professionals.","The client understands the scheduled procedure or treatment.","The consent form is signed within 24 hours of the scheduled procedure or treatment."],
 ans:[0,1,3],
 rat:{c:"Valid informed consent requires voluntariness (no coercion), adequate disclosure (risks/benefits/alternatives by the provider), and client comprehension of the procedure. A nurse witness and a 24-hour window are not validity requirements.",
 o:["Correct — consent must be freely given, free of coercion or undue influence.",
 "Correct — the provider must disclose the nature of the procedure, risks, benefits, and alternatives.",
 "One witness (often the nurse) is customary — two professionals are not required.",
 "Correct — the client must demonstrate understanding of what they are agreeing to.",
 "No rule requires signing within 24 hours of the procedure; consent obtained well in advance is valid if the client remains informed."],
 s:"Valid consent = voluntary + disclosed + understood + client has capacity. Watch for trick add-ons (witness counts, time windows) that are not required."},
 ref:"Demo practice set · item 52"},

/* ── Item 53 ── */
{id:"DEMO-053", t:"multi", cn:"PSY", sys:"PSYCH", topic:"Sexual assault · therapeutic response", d:1, b:-0.25, cj:"generate", tags:["communication","trauma"],
 stem:"The nurse is talking with a client who has been sexually assaulted. The client states, “I never should have walked home late at night. I am to blame for what has happened to me.” Which of the following would be an appropriate response for the nurse to make? Select all that apply.",
 opts:["“The police officers who brought you into the hospital will be with you during this interview.”","“You should take a warm, calming shower in order to feel more relaxed.”","“You did the best you could in very difficult circumstances.”","“Sometimes the victim’s behavior causes the violence.”","“You are safe here.”"],
 ans:[2,4],
 rat:{c:"Appropriate responses validate the survivor, remove self-blame, and restore safety. Anything implying the client caused the assault, or that destroys forensic evidence (showering), is inappropriate.",
 o:["Do not promise police presence during the interview — that is not the nurse’s call and may feel coercive.",
 "Showering destroys forensic evidence and is discouraged until the examination is complete.",
 "Correct — removes self-blame and affirms the client’s actions under threat.",
 "FALSE — the assailant, not the victim, causes sexual violence. This reinforces the myth of victim culpability.",
 "Correct — reinforcing present safety reduces fear and supports therapeutic communication."],
 s:"Trauma-informed care: believe, remove blame, ensure safety, offer control. Never blame, never promise outcomes, never advise evidence-destroying actions (shower, douche, change clothes) pre-exam."},
 ref:"Demo practice set · item 53"},

/* ── Item 54 ── */
{id:"DEMO-054", t:"multi", cn:"PSY", sys:"NEURO", topic:"Alzheimer’s disease · interventions", d:1, b:-0.3, cj:"generate", tags:["neuro","intervention"],
 stem:"The nurse is planning care for a client with moderate Alzheimer’s disease (AD). Which of the following interventions should the nurse include in the client’s plan of care? Select all that apply.",
 opts:["Establish a daily routine for the client.","Assist the client to void every 2 hours.","Introduce self upon interacting with the client.","Display a clock and calendar in the client’s room.","Keep the client’s television on during the day to distract the client."],
 ans:[0,1,2,3],
 rat:{c:"Structure reduces agitation: predictable routines, scheduled toileting, re-orientation through introductions, and visible clocks/calendars all support the client with moderate AD.",
 o:["Correct — consistent daily routines reduce confusion and behavioral distress.",
 "Correct — scheduled voiding (q2h) promotes continence and prevents accidents.",
 "Correct — introducing yourself re-orients the client with each interaction.",
 "Correct — clocks and calendars provide environmental orientation cues.",
 "Constant TV noise increases agitation and confusion — keep stimulation low and purposeful."],
 s:"AD care kit: routine, cues (clock/calendar/labels), scheduled toileting, introduce yourself, low-stimulation environment, simple choices."},
 ref:"Demo practice set · item 54"},

/* ── Item 55 ── */
{id:"DEMO-055", t:"single", cn:"PSY", sys:"PSYCH", topic:"Grief · preschooler", d:2, b:0.5, cj:"analyze", tags:["pediatrics","grief"],
 stem:"A parent is discussing with the nurse about the behaviors of a 4-year-old child following the death of a grandparent. The nurse should understand that the child may be experiencing dysfunctional grieving if the parent reports that the child",
 opts:["conducts mock funerals with stuffed animals","refuses to go to sleep at night","continues to talk about the grandparent coming to visit","asks to play with the grandparent while at the cemetery"],
 ans:1,
 rat:{c:"Play rituals, magical thinking about the dead returning, and talking to the deceased are NORMAL for a preschooler’s grief. Persistent refusal to sleep signals distress (fear, anxiety) beyond normal preschool grief and needs follow-up.",
 o:["Reenacting funerals in play is a normal, healthy way preschoolers process death.",
 "Correct — persistent sleep refusal indicates unresolved distress/anxiety and is the dysfunctional pattern to evaluate.",
 "Believing the grandparent will come back reflects the preschooler’s magical thinking (death is reversible at this age) — expected.",
 "Wanting to play with the deceased at the cemetery is the same normal magical thinking."],
 s:"Preschool grief norms: play reenactment, talking to/about the deceased, believing death is reversible. Red flags: major sleep/appetite disruption, regression, persistent fear."},
 ref:"Demo practice set · item 55"},

/* ── Item 56 ── */
{id:"DEMO-056", t:"single", cn:"BCC", sys:"CV", topic:"Nutrition · low-sodium diet", d:1, b:-0.3, cj:"evaluate", tags:["nutrition","teaching"],
 stem:"The nurse has taught a client who has been ordered a low-sodium diet about appropriate food choices. Which of the following statements by the client would indicate a correct understanding of the teaching?",
 opts:["“I will eat steamed, fresh broccoli with herbs and spices for an evening meal.”","“I will add cottage cheese and other dairy products to my daily diet.”","“I am glad I can still enjoy eating cereals, such as bran flakes with raisins.”","“I am glad I can eat lean meats daily because I eat ham sandwiches for an afternoon meal.”"],
 ans:0,
 rat:{c:"Fresh vegetables seasoned with herbs and spices (not salt) are naturally low sodium — the correct choice. Cottage cheese, many boxed cereals, and cured meats like ham are high-sodium traps.",
 o:["Correct — fresh produce with herb/spice seasoning keeps sodium low.",
 "Cottage cheese is one of the highest-sodium dairy products.",
 "Many ready-to-eat cereals (and raisin-bran types) carry surprising sodium loads — check labels.",
 "Ham is cured and brined — a concentrated sodium source despite being “lean meat.”"],
 s:"Low-sodium green light: fresh/plain foods, herbs, citrus. Red light: cured (ham/bacon), brined (pickles), canned, instant, processed cheese and many boxed cereals."},
 ref:"Demo practice set · item 56"},

/* ── Item 57 ── */
{id:"DEMO-057", t:"single", cn:"BCC", sys:"REPI", topic:"Mastectomy · arm rehabilitation", d:1, b:-0.2, cj:"evaluate", tags:["rehab","oncology","teaching"],
 stem:"The nurse is caring for a client who had a left modified radical mastectomy. The client received discharge instructions for performing range-of-motion (ROM) exercises on her left arm. Which of the following, if reported by the client on her return visit to the clinic, would indicate to the nurse that the instructions have been followed correctly?",
 opts:["regular squeezing of a tennis ball in her left hand","placing her left palm against a wall and “climbing” the wall with the left fingers","carrying light hand weights while walking 1 mile every other day","performing isometric exercises with both arms extended"],
 ans:1,
 rat:{c:"Wall climbing (finger “ladder”) progressively recovers shoulder flexion/abduction — the classic post-mastectomy ROM exercise, done gently and daily.",
 o:["A tennis ball improves grip and hand strength but does not restore SHOULDER range of motion.",
 "Correct — wall climbing progressively restores shoulder flexion/abduction after mastectomy.",
 "Weight carrying stresses the arm at a fixed range — not a progressive ROM exercise (and heavy/repetitive loading is discouraged early).",
 "Isometrics with arms extended strengthen without moving the joint — they do not restore functional shoulder range."],
 s:"Post-mastectomy arm program: wall/finger ladder climbing, pendulum swings, gradually widening activities. Think “progressive shoulder range,” not grip or fixed holds."},
 ref:"Demo practice set · item 57"},

/* ── Item 58 ── */
{id:"DEMO-058", t:"multi", cn:"RRP", sys:"NEURO", topic:"Expressive aphasia · communication", d:2, b:0.5, cj:"evaluate", tags:["neuro","rehab","teaching"],
 stem:"The nurse is planning care for a client who has expressive aphasia after a left-sided stroke. Which of the following statements by the client’s spouse would indicate a correct understanding of the client’s communication abilities and interaction needs? Select all that apply.",
 opts:["“My spouse’s response of ‘fine’ when asked how the day has been may or may not be what my spouse meant to communicate.”","“I can anticipate what my spouse wants to say, so I complete my spouse’s sentences to make communication quicker.”","“I will purchase a picture board to help my spouse express common needs, thoughts, and feelings that are difficult to communicate.”","“My spouse’s angry response when we have a conversation makes me hesitant to try further communication.”","“I have arranged for my spouse to meet with a speech therapist twice each week to improve communication skills.”"],
 ans:[0,2,4],
 rat:{c:"Expressive aphasia means the client KNOWS what to say but cannot form it. Correct supports: interpret responses carefully, offer augmentative tools (picture board), and continue speech therapy. Finishing sentences and withdrawing from communication are counterproductive.",
 o:["Correct — automatic responses may not match intent; verify meaning gently.",
 "Completing sentences robs the client of practice and imposes the other person’s words.",
 "Correct — a picture board gives the client a real expressive channel.",
 "Withdrawing from communication worsens isolation and frustration — the opposite of the interaction needs.",
 "Correct — continued speech-language therapy is the standard of care for aphasia recovery."],
 s:"Expressive aphasia = ideas intact, output broken. Support: allow time, yes/no and picture tools, speech therapy. Never speak for the client, never avoid talking."},
 ref:"Demo practice set · item 58"},

/* ── Item 59 ── */
{id:"DEMO-059", t:"single", cn:"RRP", sys:"MSK", topic:"Buck traction · assessment", d:2, b:0.5, cj:"act", tags:["safety","musculoskeletal"],
 stem:"The nurse is caring for a client who is in Buck traction. Which of the following would require immediate intervention?",
 opts:["A pillow is placed under the knee.","The foot is 2 in (5 cm) away from the foot plate.","The weights attached to the pulley are 6 in (15 cm) from the floor.","A pillow is placed under the lower leg with the heel off the bed."],
 ans:0,
 rat:{c:"Buck (extension) traction pulls the leg straight — a pillow under the knee flexes the hip/knee, disengages the pull, and can defeat the traction entirely; remove it immediately.",
 o:["Correct — knee flexion breaks the straight-line pull of Buck traction; intervene now.",
 "In Buck (boot) traction there is no foot plate — the boot holds the leg; distance from a foot plate applies to other setups, not this finding to act on. (In skeletal leg traction the foot must NOT touch the foot plate.)",
 "Weights hanging free, 6 in off the floor, are correctly positioned — they must never rest on the floor.",
 "A pillow under the lower leg with the heel floating PREVENTS heel pressure — appropriate."],
 s:"Traction invariants: straight alignment (no knee pillows), weights hanging free, ropes in the pulleys, no knots against the pulley, skin/neurovascular checks."},
 ref:"Demo practice set · item 59"},

/* ── Item 60 ── */
{id:"DEMO-060", t:"single", cn:"HPM", sys:"NEURO", topic:"Alzheimer’s disease · home safety", d:1, b:-0.25, cj:"evaluate", tags:["neuro","teaching","safety"],
 stem:"The nurse has taught the adult child caregiver of a client with moderate Alzheimer’s disease (AD) about home care. Which of the following statements by the adult child would indicate a correct understanding of the teaching?",
 opts:["“I will only allow my parent to smoke while my parent is outdoors.”","“I will place a picture on the bathroom door to show which room in our home is the bathroom.”","“I will encourage family members to visit in large groups to keep my parent interested in the conversation.”","“I will encourage my parent to take walks in the park when the weather permits to get the exercise needed.”"],
 ans:1,
 rat:{c:"Visual labels (a picture of a toilet on the bathroom door) help the moderately impaired client find and use the bathroom independently — a correct adaptation.",
 o:["Supervising smoking is not enough — smoking should stop entirely for a cognitively impaired client (fire and injury risk even outdoors is not the tested principle; cessation/supervision means stopping).",
 "Correct — picture cues support independent functioning and continence.",
 "Large groups overwhelm and disorient the client with AD — visit one or two at a time.",
 "Unsupervised walks in a public park risk wandering and getting lost; walks must be supervised."],
 s:"Moderate AD home kit: label rooms with pictures, small calm visits, supervised outings, lock hazards, structured routine."},
 ref:"Demo practice set · item 60"},

/* ── Item 61 ── */
{id:"DEMO-061", t:"single", cn:"BCC", sys:"GI", topic:"Diverticulosis · teaching", d:1, b:-0.25, cj:"generate", tags:["nutrition","teaching"],
 stem:"The nurse is teaching a client newly diagnosed with diverticulosis. Which of the following information should the nurse include?",
 opts:["“Limit your daily fluid intake to 2 L to avoid bloating.”","“You may be prescribed a bulk-forming laxative.”","“Limit your intake of dairy products such as milk and yogurt.”","“You should avoid consuming cooked vegetables.”"],
 ans:1,
 rat:{c:"Diverticulosis is managed with a high-fiber diet, adequate fluids, and often a bulk-forming agent (psyllium) to keep stool soft and prevent diverticulitis.",
 o:["Fluids should be INCREASED with fiber (≈ 2–3 L/day) — limiting fluids worsens constipation.",
 "Correct — bulk-forming laxatives supplement dietary fiber and keep stool soft.",
 "Dairy restriction has no role in diverticulosis management.",
 "High-fiber foods, including vegetables, are encouraged — avoiding them is backwards."],
 s:"Diverticulosis = quiet pouches: fiber + fluids + bulk agent. Diverticulitis = inflamed: NPO/clears + antibiotics during the acute phase."},
 ref:"Demo practice set · item 61"},

/* ── Item 62 ── */
{id:"DEMO-062", t:"single", cn:"PHA", sys:"INF", topic:"Medication safety · unfamiliar dose", d:1, b:-0.3, cj:"act", tags:["medication","safety"],
 stem:"The nurse is preparing to administer lorazepam 2 mg, IV, now to a client who is scheduled for surgery in 30 minutes. The nurse is unfamiliar with the dosage for the medication. Which of the following actions should the nurse take next?",
 opts:["Check the medication dosage in a medication reference source.","Ask another nurse whether the prescribed dose is a safe dose.","Clarify that the dose is correct with the primary health care provider.","Contact the pharmacist to verify the safe dosage range for the medication."],
 ans:0,
 rat:{c:"Before escalating, the nurse consults an authoritative medication reference — that is the professional standard for verifying an unfamiliar dose.",
 o:["Correct — look it up first in a current, authoritative reference (drug guide/pharmacy database).",
 "Another nurse’s recollection is not an authoritative source.",
 "Calling the provider is unnecessary until the reference raises a concern.",
 "The pharmacist is a backup resource — the first step is checking the reference yourself."],
 s:"Unfamiliar drug/dose ladder: reference first → pharmacist if still unclear → hold and clarify with the prescriber if a problem appears. Never administer what you cannot verify."},
 ref:"Demo practice set · item 62"},

/* ── Item 63 ── */
{id:"DEMO-063", t:"single", cn:"PHA", sys:"PSYCH", topic:"Antipsychotics · neuroleptic malignant syndrome", d:2, b:0.6, cj:"recognize", tags:["medication","priority"],
 stem:"The nurse is caring for a client who is receiving a high dose of a phenothiazine. When evaluating the client for a life-threatening syndrome related to the medication, it would be a priority for the nurse to report",
 opts:["dry mouth","orthostatic hypotension","fever","photophobia"],
 ans:2,
 rat:{c:"Fever in a client on a high-potency/high-dose antipsychotic is the hallmark of neuroleptic malignant syndrome (with rigidity and autonomic instability) — a life-threatening emergency that must be reported immediately.",
 o:["Dry mouth is a common anticholinergic side effect — annoying, not lethal.",
 "Orthostatic hypotension is a common adverse effect managed by slow position changes.",
 "Correct — fever (with muscle rigidity/autonomic changes) signals NMS: stop the drug, report now.",
 "Photophobia is a minor anticholinergic-type effect."],
 s:"NMS triad: FEVER + muscle rigidity + autonomic instability (tachycardia, labile BP) + elevated CK. It kills — fever is never a routine side effect to watch on an antipsychotic."},
 ref:"Demo practice set · item 63"},


/* ── Item 71 ── */
{id:"DEMO-071", t:"multi", cn:"PHA", sys:"HEME", topic:"Transfusion reaction · response", d:1, b:-0.2, cj:"act", tags:["transfusion","priority","safety"],
 stem:"The nurse is caring for a client who is receiving a blood transfusion and states, “I feel chilled and am having back pain.” Which of the following actions should the nurse take? Select all that apply.",
 opts:["Stop the transfusion.","Check the client’s vital signs.","Notify the client’s primary health care provider.","Return the blood and infusion tubing to the blood bank.","Infuse 5% dextrose in water through the intravenous catheter.","Administer a dose of an antiemetic prescribed p.r.n. to the client."],
 ans:[0,1,2,3],
 rat:{c:"Chills with back pain is a possible hemolytic transfusion reaction: stop the blood immediately, maintain saline (never dextrose), check vitals, notify the provider, and return the unit + tubing to the blood bank for investigation.",
 o:["Correct — stop the transfusion at once and keep the IV line open with 0.9% saline.",
 "Correct — baseline/repeat vital signs guide the response.",
 "Correct — the provider must be notified immediately.",
 "Correct — the blood bag and tubing go back to the blood bank for a reaction workup.",
 "Dextrose solutions are incompatible with blood — maintain the line with normal saline only.",
 "An antiemetic treats a symptom; it does not address a possible hemolytic reaction and is not the priority action set."],
 s:"Transfusion reaction drill: STOP → SALINE → VITALS → NOTIFY → RETURN UNIT + urine sample. Never D5W, never restart the blood."},
 ref:"Demo practice set · item 71"},

/* ── Item 72 ── */
{id:"DEMO-072", t:"multi", cn:"PHA", sys:"GI", topic:"Total parenteral nutrition · therapy", d:1, b:-0.25, cj:"generate", tags:["nutrition","iv-therapy"],
 stem:"The nurse is preparing a staff education program about total parenteral nutrition (TPN). Which of the following information should the nurse include? Select all that apply.",
 opts:["“The TPN intravenous tubing should be changed once a week.”","“TPN can be administered through a peripherally inserted central catheter (PICC).”","“Clients receiving TPN should be weighed daily.”","“An infusion pump is used to deliver TPN.”","“Serum glucose levels should be monitored in clients receiving TPN.”"],
 ans:[1,2,3,4],
 rat:{c:"TPN is a concentrated hypertonic formula requiring a central line (PICC qualifies), an infusion pump for precise control, daily weights to track response, and glucose monitoring for hyperglycemia. Tubing is changed per policy — far more often than weekly (typically every 24 hours).",
 o:["TPN tubing is changed every 24 hours (or per policy) with the bag — weekly is a contamination risk.",
 "Correct — PICC tips sit in central circulation, where hypertonic TPN is safely diluted.",
 "Correct — daily weights (same scale, same time) track fluid/nutrition response.",
 "Correct — a pump controls the rate precisely; sudden TPN shifts destabilize glucose and fluid balance.",
 "Correct — TPN carries a high glucose load; monitor serum glucose and urine glucose as ordered."],
 s:"TPN = central line + pump + daily weight + glucose checks; tubing changes with each bag (24 h). Wean gradually — never stop abruptly (rebound hypoglycemia)."},
 ref:"Demo practice set · item 72"},

/* ── Item 73 ── */
{id:"DEMO-073", t:"single", cn:"PHA", sys:"PSYCH", topic:"Lithium · client teaching", d:1, b:-0.2, cj:"evaluate", tags:["medication","teaching"],
 stem:"The nurse has taught a client with bipolar I disorder who is experiencing a manic episode and is receiving lithium. Which of the following statements by the client would indicate a correct understanding of the teaching?",
 opts:["“I will increase my oral fluid intake to 2 to 3 L daily while taking the medication.”","“I will experience an improvement in my condition 5 weeks after starting the medication.”","“I should decrease my intake of dietary sodium after starting the medication.”","“I should limit time spent in a sauna to 1 hour weekly while taking the medication.”"],
 ans:0,
 rat:{c:"Lithium is excreted by the kidneys and handled like sodium — maintaining 2–3 L/day of fluids (and consistent sodium) prevents toxic accumulation.",
 o:["Correct — 2 to 3 L of fluid daily keeps lithium levels stable and prevents toxicity.",
 "Therapeutic effect typically appears in 1 to 2 weeks (serum levels at 5–7 days) — not 5 weeks.",
 "LOW sodium causes the kidneys to reabsorb lithium and toxicity rises — sodium intake stays consistent/adequate.",
 "Saunas (with sweating and dehydration) increase lithium toxicity — avoid them, don’t budget an hour."],
 s:"Lithium safety: fluids 2–3 L, steady salt, avoid sweating/dehydration/diuretics/NSAIDs, report coarse tremor, GI upset, confusion. Therapeutic level 0.6–1.2 mEq/L."},
 ref:"Demo practice set · item 73"},

/* ── Item 74 ── */
{id:"DEMO-074", t:"single", cn:"PHA", sys:"PSYCH", topic:"Haloperidol · adverse effects", d:2, b:0.45, cj:"recognize", tags:["medication","priority"],
 stem:"The nurse has administered haloperidol to a client with schizophrenia who is agitated. Which of the following findings would require immediate follow-up?",
 opts:["continued lack of motivation","reports of muscle stiffness","inappropriate emotional expressions","difficulty focusing due to blurred vision"],
 ans:1,
 rat:{c:"Muscle stiffness after haloperidol can be the first sign of neuroleptic malignant syndrome (or a severe dystonic reaction) — both urgent; report immediately.",
 o:["Lack of motivation (negative symptom of schizophrenia) is not a medication emergency.",
 "Correct — rigidity/stiffness signals NMS or severe extrapyramidal reaction: immediate follow-up.",
 "Inappropriate affect is a symptom of the illness, not an emergency.",
 "Blurred vision is an anticholinergic nuisance effect — annoying, not immediately dangerous."],
 s:"Any antipsychotic + muscle rigidity/fever → NMS until proven otherwise. Everything else here is disease symptomatology or minor side effects."},
 ref:"Demo practice set · item 74"},

/* ── Item 75 ── */
{id:"DEMO-075", t:"single", cn:"PHA", sys:"ENDO", topic:"Propylthiouracil · teaching", d:2, b:0.5, cj:"generate", tags:["medication","teaching"],
 stem:"The nurse is teaching a client who is receiving newly prescribed propylthiouracil. Which of the following information should the nurse include?",
 opts:["“Carry emergency identification with you listing your condition and medication regimen.”","“The medication dose will need to be reduced if you develop agranulocytosis.”","“You will experience weight loss if the medication is effective.”","“Increase your daily intake of foods containing iodine.”"],
 ans:0,
 rat:{c:"Antithyroid therapy warrants medical identification so emergency responders know the condition and drugs; agranulocytosis is a STOP-the-drug emergency.",
 o:["Correct — carry ID listing hyperthyroidism and the medication (and know the signs of agranulocytosis: fever, sore throat, easy bruising).",
 "Agranulocytosis means the medication is STOPPED and the provider contacted — not dose-reduced.",
 "Effective treatment of hyperthyroidism RESTORES weight previously lost — expect weight gain, not loss.",
 "Added iodine works against antithyroid therapy — do not increase iodine-containing foods."],
 s:"PTU/methimazole teaching: med ID, watch for sore throat/fever (agranulocytosis), expect weight gain as metabolism normalizes, no extra iodine."},
 ref:"Demo practice set · item 75"},

/* ── Item 76 ── */
{id:"DEMO-076", t:"single", cn:"PHA", sys:"CV", topic:"Beta blockers · contraindications", d:1, b:-0.3, cj:"analyze", tags:["medication","safety"],
 stem:"The nurse is preparing to administer a beta blocker to a client. Which of the following would be a contraindication to administer the medication?",
 opts:["heart block","myocardial infarction (MI)","heart failure","angina pectoris"],
 ans:0,
 rat:{c:"Beta blockers slow conduction through the AV node — in existing heart block they can cause complete (third-degree) block and severe bradycardia, so they are contraindicated.",
 o:["Correct — AV conduction disease/heart block is the contraindication.",
 "Beta blockers are standard THERAPY after MI (mortality benefit).",
 "Beta blockers are guideline therapy for heart failure (careful initiation, but not a contraindication).",
 "Beta blockers relieve angina by reducing workload — an indication."],
 s:"Beta blocker red flags: heart block, severe bradycardia, acute decompensated heart failure, asthma (relative). MI, HF, and angina are indications."},
 ref:"Demo practice set · item 76"},

/* ── Item 77 ── */
{id:"DEMO-077", t:"multi", cn:"MOC", sys:"INF", topic:"Informed consent · staff education", d:2, b:0.5, cj:"generate", tags:["legal","teaching"],
 stem:"The nurse is planning a staff education program about informed consent. Which of the following information should the nurse include? Select all that apply.",
 opts:["“The main value of informed consent is for protection against lawsuits.”","“Clients may withdraw consent after signing the informed consent form.”","“Clients must sign the informed consent form before receiving preprocedural medication.”","“Nurses witness the signing of the informed consent form to confirm that consent is voluntary.”","“The signed consent form serves as evidence that the informed consent process has taken place.”"],
 ans:[1,2,3,4],
 rat:{c:"Informed consent protects the client’s autonomy: it can be withdrawn at any time, must be signed before sedating premedication, and the nurse’s witness role confirms voluntary signing; the form documents the process.",
 o:["Consent exists to protect CLIENT AUTONOMY, not the institution — lawsuit protection is a side effect, not the main value.",
 "Correct — consent is revocable at any time, even after signing.",
 "Correct — sedation invalidates the capacity to consent, so sign first, medicate after.",
 "Correct — the nurse witnesses that the signature was voluntary and the client was competent.",
 "Correct — the form is documentation that the consent process occurred."],
 s:"Autonomy is the point: voluntary, revocable, signed before sedation, witnessed by the nurse."},
 ref:"Demo practice set · item 77"},

/* ── Item 78 ── */
{id:"DEMO-078", t:"multi", cn:"PHA", sys:"MSK", topic:"Alendronate · client teaching", d:1, b:-0.25, cj:"evaluate", tags:["medication","teaching"],
 stem:"The nurse has taught a client who is receiving alendronate. Which of the following statements by the client would indicate a correct understanding of the teaching? Select all that apply.",
 opts:["“I will take alendronate a half hour before I eat breakfast.”","“I should avoid weight-bearing exercises while taking alendronate.”","“I should discontinue alendronate if I experience nausea or vomiting.”","“I will need to remain in an upright position for 30 minutes after I take alendronate.”","“I should notify my primary health care provider if I experience difficulty swallowing while taking alendronate.”"],
 ans:[0,3,4],
 rat:{c:"Alendronate is fiercely esophageal-toxic: take it first thing with a full glass of plain water, stay upright 30 minutes, and report dysphagia/heartburn (esophagitis). Weight-bearing exercise is encouraged — it works with the drug.",
 o:["Correct — empty stomach, plain water, 30 minutes before any food/drink/other medication.",
 "Weight-bearing exercise is ENCOURAGED — it builds bone alongside the medication.",
 "Nausea alone doesn’t mean stop — but do contact the provider; don’t self-discontinue.",
 "Correct — upright (sitting or standing) for 30 minutes prevents esophageal reflux injury.",
 "Correct — difficulty swallowing or chest pain suggests esophageal injury: notify the provider."],
 s:"Bisphosphonate mantra: first-thing, plain water, empty stomach, upright 30 minutes, no other meds; report swallowing/chest symptoms. Exercise helps, not hurts."},
 ref:"Demo practice set · item 78"},

/* ── Item 79 ── */
{id:"DEMO-079", t:"single", cn:"RRP", sys:"NEURO", topic:"Spinal cord injury · catheter care", d:2, b:0.4, cj:"prioritize", tags:["neuro","safety"],
 stem:"The nurse is developing a plan of care for a client with a spinal cord injury at C5 who has an indwelling urethral catheter. Which of the following would be a priority for the nurse to include in the plan of care?",
 opts:["encouraging the client to drink 6 to 8 glasses of fluid per day","maintaining the urine collection bag in a dependent position","teaching the client about foods high in fiber","assessing the color of the urine output"],
 ans:1,
 rat:{c:"At C5 the client cannot reposition the bag or tubing; if the bag rides above the bladder, urine refluxes and causes upper-tract infections. Keeping the drainage system below bladder level (dependent, unobstructed) is the priority.",
 o:["Hydration helps, but at C5 the greatest immediate infection risk is a mispositioned drainage system.",
 "Correct — keep the bag and tubing below the bladder, off the floor, and free of kinks to stop reflux and infection.",
 "Fiber prevents constipation (real issue at C5) but does not outrank catheter-related infection risk.",
 "Urine color checks are routine monitoring, not the priority intervention."],
 s:"Indwelling catheter ABCs: bag below bladder (dependent), unobstructed tubing, closed system, perineal care. In SCI these prevent the #1 complication: infection."},
 ref:"Demo practice set · item 79"},

/* ── Item 80 ── */
{id:"DEMO-080", t:"single", cn:"MOC", sys:"NEURO", topic:"Prioritization · autonomic dysreflexia", d:2, b:0.6, cj:"prioritize", tags:["priority","neuro","emergency"],
 stem:"The nurse has been made aware that the following 4 clients require assistance. The nurse should first assist the client who had",
 opts:["an abdominal hysterectomy 5 hours ago and is reporting severe incisional pain","a transurethral resection of the prostate (TURP) yesterday and whose catheter has become disconnected","a lumbar laminectomy 2 days ago and is reporting that the feet are still numb","a spinal cord injury at T2 two weeks ago and is currently diaphoretic and nauseated"],
 ans:3,
 rat:{c:"Diaphoresis with nausea (and usually hypertension/bradycardia) in a T2 injury two weeks old is autonomic dysreflexia — a hypertensive emergency needing immediate response (sit upright, find and remove the noxious stimulus, usually bladder/bowel).",
 o:["Severe incisional pain 5 hours postop needs analgesia — urgent comfort, not life-threatening.",
 "A disconnected catheter after TURP must be reconnected aseptically soon, but it is not immediately lethal.",
 "Persistent numbness after laminectomy needs review (worsening deficit?) but is subacute.",
 "Correct — suspect autonomic dysreflexia (injury above T6): act now to prevent hypertensive stroke."],
 s:"SCI at/above T6 + sudden diaphoresis/nausea/pounding headache/throbbing BP = autonomic dysreflexia. Sit the client up, check bladder/bowel, treat the BP."},
 ref:"Demo practice set · item 80"},

/* ── Item 81 ── */
{id:"DEMO-081", t:"single", cn:"HPM", sys:"INF", topic:"HIV · viral load monitoring", d:1, b:-0.2, cj:"evaluate", tags:["infection","teaching"],
 stem:"The nurse has taught a client who has a positive laboratory test result for human immunodeficiency virus (HIV) infection. The client is scheduled for a viral load test. Which of the following statements by the client would indicate a correct understanding of the teaching?",
 opts:["“The viral load test is used to determine my response to the treatment regimen I am receiving for HIV.”","“The viral load test can rapidly detect HIV-specific antibodies in the blood.”","“I will be able to decrease the dosage of my prescribed medications if my viral load is low.”","“I am unlikely to develop acquired immune deficiency syndrome (AIDS) if my viral load is high.”"],
 ans:0,
 rat:{c:"The viral load (HIV RNA) quantifies virus in the blood and is THE measure of treatment response (goal: undetectable). Antibody detection is a different test, and dose changes are made only by the provider.",
 o:["Correct — viral load tracks how well antiretroviral therapy is suppressing the virus.",
 "Antibody detection describes screening tests (4th-generation antigen/antibody), not viral load.",
 "Clients never self-adjust antiretrovirals — dosage changes are provider-made and adherence is lifelong.",
 "A HIGH viral load means uncontrolled infection — closer to AIDS progression, not further from it."],
 s:"HIV labs: viral load = amount of virus (treatment response, goal undetectable); CD4 = immune status (AIDS threshold <200); antibody/antigen = screening/diagnosis."},
 ref:"Demo practice set · item 81"},

/* ── Item 82 ── */
{id:"DEMO-082", t:"multi", cn:"RRP", sys:"REN", topic:"24-hour urine collection · teaching", d:1, b:-0.25, cj:"generate", tags:["diagnostics","teaching"],
 stem:"The nurse is teaching a client who is scheduled for a 24-hour urine collection. Which of the following information should the nurse include? Select all that apply.",
 opts:["“You will be asked to urinate when starting the collection, and the initial urine will be discarded.”","“A sign will be posted on the bathroom door as a reminder to save your urine.”","“You will be asked to void at the end of the designated time period to complete the urine collection.”","“You should discard urine that is dark or pink in color.”","“The collected urine will be sent to the laboratory at the end of each shift.”"],
 ans:[0,1,2],
 rat:{c:"A 24-hour collection starts by emptying the bladder and DISCARDING that first void, saves every drop for 24 hours (sign as reminder), and ends with a void AT the 24-hour mark that IS added.",
 o:["Correct — the clock starts with a void that is thrown away (it represents urine already formed).",
 "Correct — a sign/reminder prevents accidental flushing of specimens.",
 "Correct — the final void at exactly 24 hours completes the collection.",
 "Never discard urine based on color — appearance does not disqualify a timed collection (report it, but save it).",
 "The entire 24-hour collection goes to the lab as one specimen at the END — not per shift."],
 s:"Timed urine rules: discard the first void, save everything after, finish with the 24-hour void, keep refrigerated/on ice if required, one container to the lab."},
 ref:"Demo practice set · item 82"},

/* ── Item 83 ── */
{id:"DEMO-083", t:"multi", cn:"HPM", sys:"ENDO", topic:"Diabetes · foot care", d:1, b:-0.3, cj:"evaluate", tags:["diabetes","teaching","safety"],
 stem:"The nurse has taught a client with diabetes mellitus (type 2) about foot care. Which of the following statements by the client would indicate a correct understanding of the teaching? Select all that apply.",
 opts:["“I will check my shoes for foreign objects prior to putting them on.”","“I should use a large, coarse file to remove dry skin from a bunion.”","“I will apply a petroleum-based ointment between my toes after bathing.”","“I should avoid crossing my legs to prevent decreased circulation to my feet.”","“I should wear new shoes for a few hours for several days until they fit well.”"],
 ans:[0,3,4],
 rat:{c:"Diabetic foot care protects sensation and circulation: shake out shoes, avoid crossing legs, and break new shoes in gradually. Coarse files injure skin, and ointment between toes macerates it — both invite infection.",
 o:["Correct — insensate feet feel no pebble inside the shoe; check every time.",
 "Coarse files/callus removal can wound the skin — use gentle skin care and professional foot care.",
 "Cream between toes holds moisture and breeds fungal/bacterial infection — apply to tops and soles only.",
 "Correct — leg crossing impairs circulation to already vulnerable feet.",
 "Correct — gradually increase new-shoe wearing time to prevent blisters."],
 s:"Diabetic foot rules: daily inspection, check shoes, lukewarm water, no self-surgery on calluses, moisturize (but not between toes), break in shoes slowly, never go barefoot."},
 ref:"Demo practice set · item 83"},

/* ── Item 84 ── */
{id:"DEMO-084", t:"multi", cn:"HPM", sys:"MSK", topic:"Hip arthroplasty · preoperative teaching", d:2, b:0.5, cj:"generate", tags:["surgery","teaching","musculoskeletal"],
 stem:"The nurse is teaching a client who is scheduled for a total hip arthroplasty via a posterior approach. Which of the following information should the nurse include? Select all that apply.",
 opts:["“The type of prosthesis used is based on the muscle strength and joint function of your upper extremities.”","“Do not bend the affected hip more than 90 degrees after surgery.”","“Skin preparation and cleansing is mandatory before surgery.”","“Use an elevated toilet seat for at least 6 weeks after surgery.”","“You can resume sexual intercourse after surgery if your partner is in a dependent position.”"],
 ans:[1,2,3,4],
 rat:{c:"Posterior-approach hip precautions prevent dislocation: no hip flexion past 90°, raised toilet seat, and safe positioning for intercourse (partner-dependent avoids excessive flexion). Preoperative skin cleansing reduces surgical site infection.",
 o:["Prosthesis selection is based on bone quality, anatomy, and surgeon assessment — not upper extremity strength (that consideration belongs to assistive-device planning).",
 "Correct — flexion beyond 90° (plus adduction past midline and internal rotation) risks posterior dislocation.",
 "Correct — preoperative chlorhexidine skin prep lowers infection risk.",
 "Correct — an elevated seat keeps hip flexion under 90° during toileting.",
 "Correct — partner-dependent positioning keeps the operative hip in a safe range."],
 s:"Posterior hip precautions: no bending past 90°, no crossing legs, no internal rotation, no low seats — typically 6 weeks (per surgeon)."},
 ref:"Demo practice set · item 84"},

/* ── Item 85 ── */
{id:"DEMO-085", t:"single", cn:"PHA", sys:"CV", topic:"IV therapy · complications", d:1, b:-0.2, cj:"analyze", tags:["iv-therapy","assessment"],
 stem:"The nurse is caring for a client who is receiving an intravenous infusion through a peripheral VAD. The client reports sharp pain at the VAD site. The nurse notes the intravenous fluid is infusing more slowly than prescribed. The nurse should recognize that the client is most likely experiencing",
 opts:["venous spasm","nerve damage","septicemia","hematoma"],
 ans:0,
 rat:{c:"Sharp pain along the vein with a slowed infusion is the signature of venous spasm — the vein constricts around the catheter (often from cold or irritant fluids), producing pain and reduced flow.",
 o:["Correct — sharp pain + slowed flow = venous spasm; warm the bag/slow the rate and reassess.",
 "Nerve damage causes burning/tingling radiating beyond the site, typically without a flow change.",
 "Septicemia is systemic (fever, chills) — not focal sharp pain with slow flow.",
 "A hematoma is a localized bruise from failed puncture — it wouldn’t explain the ongoing sharp pain pattern."],
 s:"IV complication quick key: sharp pain + slow infusion = spasm; pain + swelling/cool = infiltration; pain + red cord = phlebitis; fever = systemic."},
 ref:"Demo practice set · item 85"},

/* ── Item 86 ── */
{id:"DEMO-086", t:"single", cn:"PHA", sys:"CV", topic:"Central venous access · blood draws", d:2, b:0.5, cj:"evaluate", tags:["iv-therapy","safety"],
 stem:"The nurse has attended a staff education program about obtaining blood specimens from a central venous access device (VAD). Which of the following statements by the nurse would require follow-up?",
 opts:["“I will use a 3 mL syringe to flush the catheter port.”","“The injection cap should be cleansed with antiseptic and allowed to air-dry.”","“I will aspirate 5 mL of blood and discard the syringe in the biohazard container before obtaining the specimen.”","“The infusion should be turned off for at least 1 minute before the specimen is aspirated.”"],
 ans:0,
 rat:{c:"Small syringes generate dangerous high pressure that can rupture a central catheter — flush with 10 mL (or larger) syringes using a push-pause technique.",
 o:["Requires follow-up — a 3 mL syringe exerts pressure that can split the catheter; use a 10 mL syringe.",
 "Correct practice — scrub the cap with antiseptic and let it dry for full effect.",
 "Correct — discard the initial 5 mL (contains heparin/saline and diluted blood) before drawing the specimen.",
 "Correct — stopping the infusion briefly prevents the specimen from being diluted or altered."],
 s:"Central line rules: 10 mL or larger syringes only, aseptic cap prep, discard the first 5 mL, pause infusions before drawing."},
 ref:"Demo practice set · item 86"},

/* ── Item 87 ── */
{id:"DEMO-087", t:"single", cn:"HPM", sys:"MSK", topic:"Osteoporosis · prevention", d:1, b:-0.3, cj:"evaluate", tags:["teaching","musculoskeletal"],
 stem:"The nurse has taught about preventing osteoporosis to a 45-year-old client who has had a hysterectomy and bilateral salpingo-oophorectomy. Which of the following statements by the client would indicate correct understanding of the teaching?",
 opts:["“I will begin to take dancing lessons.”","“I will get more rest at night.”","“I will take a multivitamin supplement daily.”","“I will add more fiber to my diet.”"],
 ans:0,
 rat:{c:"After surgical menopause, bone loss accelerates — weight-bearing exercise like dancing is the concrete lifestyle measure that builds bone.",
 o:["Correct — dancing is weight-bearing exercise, the specific prescription for bone density plus calcium/vitamin D.",
 "More rest does nothing for bone density.",
 "A generic multivitamin is no substitute for adequate calcium (1,000–1,200 mg) and vitamin D.",
 "Fiber helps the bowel, not the bones."],
 s:"Osteoporosis prevention trio: weight-bearing exercise + calcium + vitamin D (plus smoking cessation and moderating alcohol)."},
 ref:"Demo practice set · item 87"},

/* ── Item 88 ── */
{id:"DEMO-088", t:"single", cn:"PHA", sys:"CV", topic:"Peripheral VAD · insertion technique", d:1, b:-0.25, cj:"act", tags:["iv-therapy","safety"],
 stem:"The nurse is preparing to insert a peripheral venous access device (VAD) for a client. Which of the following actions should the nurse take?",
 opts:["Ask the client to open and close the fist multiple times.","Tap the client’s vein multiple times to promote dilation.","Apply the tourniquet 9 to 10 in (22.5 to 25 cm) above the venipuncture site.","Palpate for a vein after cleansing the selected site."],
 ans:0,
 rat:{c:"Gentle fist opening/closing (without “pumping,” and released before insertion) engorges veins for easier cannulation.",
 o:["Correct — opening and closing the fist promotes venous filling (avoid excessive pumping).",
 "Tapping may cause bruising or vessel constriction — tapping “multiple times” is discouraged.",
 "The tourniquet goes 3 to 4 in (7.5 to 10 cm) above the site — 9 to 10 inches is far too high.",
 "Palpate BEFORE cleansing (before sterile gloves); after cleansing, don’t touch the site again."],
 s:"VAD insertion order: tourniquet 3–4 in above, fist gentle open/close, palpate, cleanse, don’t re-touch, insert bevel up."},
 ref:"Demo practice set · item 88"},

/* ── Item 89 ── */
{id:"DEMO-089", t:"single", cn:"RRP", sys:"INTG", topic:"Burns · inhalation injury", d:2, b:0.55, cj:"recognize", tags:["emergency","respiratory","assessment"],
 stem:"The nurse is assessing a newly admitted client who sustained partial-thickness (second-degree) burns to the anterior thorax in a house fire. Which of the following findings would require immediate follow-up?",
 opts:["dizziness and confusion","hypoactive bowel sounds and nausea","vesicular breath sounds throughout the lung fields","pain rated 5 on a scale of 0 (no pain) to 10 (severe pain)"],
 ans:0,
 rat:{c:"Dizziness and confusion after an enclosed fire signal carbon monoxide poisoning or hypoxia from inhalation injury — the leading cause of death in burn patients. Airway and oxygenation outrank everything else listed.",
 o:["Correct — neurologic changes point to CO poisoning/inhalation injury: assess airway and oxygenation now.",
 "A modest ileus (hypoactive bowel sounds, nausea) is a common systemic burn effect — monitor.",
 "Vesicular (normal) breath sounds are reassuring.",
 "Pain 5/10 with partial-thickness burns is expected and treated on schedule."],
 s:"Burn priority = AIRWAY: singed nasal hairs, voice change, stridor, confusion/combative (CO), enclosed-space fire. Treat pain and ileus after breathing."},
 ref:"Demo practice set · item 89"},

/* ── Item 90 ── */
{id:"DEMO-090", t:"single", cn:"BCC", sys:"GI", topic:"Hiatal hernia · teaching", d:1, b:-0.2, cj:"evaluate", tags:["nutrition","teaching"],
 stem:"The nurse has taught a client with a hiatal hernia about interventions for the condition. Which of the following statements by the client would indicate a correct understanding of the teaching?",
 opts:["“I will consume 3 regular-sized meals daily.”","“Wearing an abdominal binder can help relieve symptoms.”","“I should elevate the head of the bed on 6 in (15 cm) blocks.”","“Eating foods with a high fat content will increase gastric emptying.”"],
 ans:2,
 rat:{c:"Elevating the head of the bed on blocks uses gravity to prevent nighttime reflux — the classic hiatal hernia intervention.",
 o:["Small frequent meals are recommended — three large meals distend the stomach and worsen reflux.",
 "Abdominal binders increase intra-abdominal pressure and worsen reflux.",
 "Correct — 6-in blocks under the head of the bed reduce reflux during sleep.",
 "High-fat foods DELAY gastric emptying and worsen symptoms."],
 s:"Hiatal hernia/GERD package: small meals, no late eating, head of bed elevated, avoid fatty/spicy/acidic foods, alcohol, and tight clothing."},
 ref:"Demo practice set · item 90"},

/* ── Item 91 ── */
{id:"DEMO-091", t:"multi", cn:"RRP", sys:"MSK", topic:"Gout · assessment findings", d:1, b:-0.2, cj:"recognize", tags:["assessment","musculoskeletal"],
 stem:"The nurse is assessing a client with suspected gout. Which of the following findings would support a diagnosis of gout? Select all that apply.",
 opts:["elevated serum uric acid level","a swollen, red joint","reports of moderate fatigue","distal extremities cool to touch","pain associated with movement of the affected extremity","intolerance of dairy products"],
 ans:[0,1,4],
 rat:{c:"Gout = urate crystal deposition in a joint: hyperuricemia plus an acutely inflamed (red, swollen, exquisitely painful) joint, classically the first toe, hurting with movement.",
 o:["Correct — elevated uric acid underlies crystal formation.",
 "Correct — the affected joint is red, swollen, hot.",
 "Fatigue is nonspecific and not a gout hallmark.",
 "Cool extremities suggest vascular disease, not gout.",
 "Correct — movement of the inflamed joint is painful (even bed sheets hurt).",
 "Dairy intolerance suggests lactose issues — unrelated (dairy actually lowers gout risk)."],
 s:"Gout cluster: hyperuricemia + monoarticular red/hot/swollen joint (great toe) + exquisite movement pain. Cool limbs and dairy symptoms belong elsewhere."},
 ref:"Demo practice set · item 91"},

/* ── Item 92 ── */
{id:"DEMO-092", t:"single", cn:"RRP", sys:"REPI", topic:"Endometriosis · assessment", d:1, b:-0.2, cj:"recognize", tags:["assessment","reproductive"],
 stem:"The nurse is assessing a client with suspected endometriosis. Which of the following findings would support a diagnosis of endometriosis?",
 opts:["dyspareunia","hot flashes","weight gain","amenorrhea"],
 ans:0,
 rat:{c:"Endometrial implants outside the uterus cause painful intercourse (deep dyspareunia), dysmenorrhea, and pelvic pain — the classic triad.",
 o:["Correct — deep pelvic pain during intercourse reflects implants behind the uterus/ligaments.",
 "Hot flashes reflect estrogen deficiency (menopause) — not endometriosis.",
 "Weight gain is not a hallmark of endometriosis.",
 "Amenorrhea is absent — clients still menstruate (often with severe dysmenorrhea)." ],
 s:"Endometriosis = “3 Ds”: dysmenorrhea, dyspareunia, dyschezia (painful stools), plus infertility. Think pain, not hormone-deficiency signs."},
 ref:"Demo practice set · item 92"},

/* ── Item 93 ── */
{id:"DEMO-093", t:"single", cn:"RRP", sys:"GI", topic:"Cirrhosis · assessment", d:2, b:0.4, cj:"recognize", tags:["assessment","gastrointestinal"],
 stem:"The nurse is assessing a client with cirrhosis. Which of the following findings would be consistent with a diagnosis of cirrhosis?",
 opts:["steatorrhea","deep vein thrombosis (DVT)","high fever","spontaneous bruising"],
 ans:3,
 rat:{c:"The cirrhotic liver cannot produce clotting factors and sequesters platelets, so spontaneous bruising (and bleeding) is a classic finding of advanced liver disease.",
 o:["Steatorrhea points to pancreatic insufficiency or fat-malabsorption disease — not the primary cirrhosis marker tested here.",
 "DVT is a venous stasis/hypercoagulable problem, unrelated to cirrhosis (which causes bleeding, not clotting).",
 "High fever suggests infection (e.g., cholangitis, spontaneous bacterial peritonitis is possible but not a hallmark finding of cirrhosis itself).",
 "Correct — decreased clotting factor synthesis + thrombocytopenia cause easy, spontaneous bruising."],
 s:"Cirrhosis cluster: jaundice, spider angiomas, palmar erythema, ascites, caput medusae, gynecomastia, bruising/bleeding, asterixis, encephalopathy."},
 ref:"Demo practice set · item 93"},

/* ── Item 94 ── */
{id:"DEMO-094", t:"single", cn:"RRP", sys:"REPI", topic:"Syphilis · primary stage", d:1, b:-0.25, cj:"recognize", tags:["assessment","infection"],
 stem:"The nurse is assessing a male client who has suspected syphilis. Which of the following findings would support a diagnosis of syphilis?",
 opts:["urethritis","conjunctivitis","chancre lesions","penile discharge"],
 ans:2,
 rat:{c:"The painless chancre (indurated clean-based ulcer) at the entry site is the hallmark of primary syphilis, appearing about 3 weeks after exposure.",
 o:["Urethritis with discharge suggests gonorrhea or chlamydia.",
 "Conjunctivitis appears in gonococcal neonatal infection (or other conditions), not classic syphilis.",
 "Correct — a painless chancre is the primary-stage lesion of syphilis.",
 "Discharge accompanies gonococcal/chlamydial urethritis, not the chancre stage of syphilis."],
 s:"STI lesion map: painless chancre = syphilis; painful vesicles = herpes; cauliflower warts = HPV; purulent discharge = gonorrhea/chlamydia."},
 ref:"Demo practice set · item 94"},

/* ── Item 95 ── */
{id:"DEMO-095", t:"single", cn:"RRP", sys:"NEURO", topic:"Spinal shock · manifestations", d:2, b:0.45, cj:"evaluate", tags:["neuro","assessment"],
 stem:"The nurse has attended a staff education program about spinal shock following acute spinal cord injury. Follow-up is required if the nurse states that manifestations of spinal shock include",
 opts:["bowel dysfunction","bladder dysfunction","spastic paralysis below the level of injury","loss of sensation below the level of injury"],
 ans:2,
 rat:{c:"Spinal shock is the immediate areflexic phase: FLACCID paralysis, loss of sensation, and bowel/bladder dysfunction below the injury. Spasticity develops LATER as reflexes return — so attributing spastic paralysis to spinal shock requires follow-up.",
 o:["Bowel dysfunction (ileus/incontinence) is part of the areflexic picture — accurate.",
 "Bladder dysfunction (atonic retention) is a spinal shock manifestation — accurate.",
 "Correct — spinal shock is FLACCID, not spastic; spasticity emerges when spinal shock resolves.",
 "Sensory loss below the injury is expected in spinal shock — accurate."],
 s:"Spinal shock = everything below goes quiet: flaccid, areflexic, insensitive, atonic bladder/bowel. Return of reflexes (bulbocavernosus) marks its end."},
 ref:"Demo practice set · item 95"},

/* ── Item 96 ── */
{id:"DEMO-096", t:"single", cn:"RRP", sys:"CV", topic:"AV shunt · care", d:1, b:-0.25, cj:"generate", tags:["renal","safety"],
 stem:"The nurse is planning care for a client who has an arteriovenous (AV) shunt in the left arm. Which of the following interventions should the nurse include in the client’s plan of care?",
 opts:["Instruct the client to protect the AV shunt by tucking the left arm under the body while sleeping.","Check for a bruit by palpating the AV shunt.","Administer prescribed intravenous fluids through the AV shunt.","Avoid obtaining blood pressure measurements in the arm with the AV shunt."],
 ans:3,
 rat:{c:"The shunt arm must never be compressed: no BP cuffs, no venipuncture, no sleeping on it — compression can thrombose the access.",
 o:["Tucking the arm under the body compresses the shunt — it should stay free and unconstrained.",
 "A bruit is checked by LISTENING with a stethoscope; a THRILL is felt by palpation.",
 "The shunt is reserved for dialysis access only — not for fluids or medications.",
 "Correct — BP measurements compress the vessel and can clot the access; use the opposite arm."],
 s:"Fistula/graft arm rules: no BP, no draws, no tight sleeves, sleep off it; assess bruit (listen) + thrill (feel) every shift. Access loss = dialysis emergency."},
 ref:"Demo practice set · item 96"},

/* ── Item 97 ── */
{id:"DEMO-097", t:"single", cn:"RRP", sys:"RESP", topic:"Chest tubes · priority monitoring", d:2, b:0.5, cj:"prioritize", tags:["respiratory","safety"],
 stem:"The nurse is caring for a client who has a chest tube attached to a closed-chest drainage system. It would be a priority for the nurse to monitor the client for",
 opts:["tracheal deviation","pain at the insertion site","subcutaneous emphysema","redness or swelling at the insertion site"],
 ans:0,
 rat:{c:"Tracheal deviation signals a tension pneumothorax — mediastinal shift that kills by obstructing venous return and both lungs. It is the emergency finding to monitor for above all others.",
 o:["Correct — a deviated trachea (away from the affected side, with distended neck veins and hypotension) = tension pneumothorax: clamp nothing, call for help now.",
 "Insertion-site pain is expected and manageable — monitor and treat.",
 "Subcutaneous emphysema warrants monitoring and provider notification, but it is not immediately lethal.",
 "Redness/swelling suggests local infection — important, not emergent."],
 s:"Chest tube red alert: tracheal deviation + one-sided absent breath sounds + neck vein distension + hypotension = tension pneumothorax (can develop if the tube is clamped/occluded)."},
 ref:"Demo practice set · item 97"}

,

/* ── Item 99 ── */
{id:"DEMO-099", t:"single", cn:"MOC", sys:"MSK", topic:"Referrals · occupational therapy", d:1, b:-0.2, cj:"generate", tags:["delegation","rehab"],
 stem:"The nurse is caring for the following clients. The nurse should recommend a referral to an occupational therapist for the client with",
 opts:["rheumatoid arthritis (RA) who has a 2-month-old infant","an intertrochanteric hip fracture who works as a surgeon","mononucleosis who is a college student","tendonitis who is a professional tennis player"],
 ans:0,
 rat:{c:"Occupational therapy teaches adaptive techniques and devices for Activities of Daily Living — the RA mother with an infant needs joint protection and adaptive methods for infant care.",
 o:["Correct — OT addresses ADL adaptation and joint protection for infant care (positioning, lifting, adaptive equipment).",
 "A hip fracture in a surgeon concerns job demands, but the immediate rehab need is mobility (PT) — and OT referral centers on self-care adaptation.",
 "Mononucleosis needs rest and gradual return to activity — no OT indication.",
 "Tendonitis in a tennis player is a sports-medicine/PT problem (and a professional athlete has their own team)."],
 s:"OT = “occupations” = ADLs (dressing, feeding, home tasks, adaptive devices). PT = mobility, gait, strength, pain modality."},
 ref:"Demo practice set · item 99"},

/* ── Item 100 ── */
{id:"DEMO-100", t:"single", cn:"SIC", sys:"RESP", topic:"Isolation precautions · pneumonia admission", d:1, b:-0.25, cj:"generate", tags:["infection-control"],
 stem:"The nurse is preparing to admit a client who has pleuritic chest pain and is reporting a cough productive of yellow sputum for the past 1 week. The client has a pulse oximetry reading of 90% on room air. Which of the following infection control precautions should the nurse implement?",
 opts:["Use a stethoscope that is designated for use with the client only.","Wear sterile gloves when inserting a peripheral venous access device (VAD).","Assign the client to a private room with monitored negative air pressure.","Place a box of surgical masks inside the client’s room."],
 ans:0,
 rat:{c:"Bacterial pneumonia spreads by droplet/contact with respiratory secretions — dedicating care equipment (stethoscope) to the client limits fomite transmission on a shared unit.",
 o:["Correct — dedicated equipment for the client prevents cross-contamination via shared devices.",
 "Sterile gloves for peripheral VAD insertion are standard sterile technique for ANY client — not the transmission-based answer for pneumonia.",
 "Negative pressure is for AIRBORNE disease (TB, measles) — pneumonia does not require it.",
 "Masks belong OUTSIDE the door (donned before entering) for droplet precautions — a box inside the room helps no one entering."],
 s:"Community pneumonia = droplet +/- contact precautions: surgical mask before entry, dedicated equipment, private room preferred (no AIIR)."},
 ref:"Demo practice set · item 100"},

/* ── Item 101 ── */
{id:"DEMO-101", t:"single", cn:"SIC", sys:"INF", topic:"Hand hygiene · alcohol-based rub", d:2, b:0.4, cj:"generate", tags:["infection-control","teaching"],
 stem:"The nurse is planning a staff education program about infection control guidelines. Which of the following information about alcohol-based hand rub should the nurse include?",
 opts:["“Use before touching medical equipment that will come in direct contact with the client.”","“Avoid using when moving your hands from a contaminated body site to a clean body site during client care.”","“Avoid using before caring for clients who have severe neutropenia.”","“Use after contact with body excretions that do not cause your hands to be visibly soiled.”"],
 ans:3,
 rat:{c:"Alcohol-based hand rub is the preferred method whenever hands are not visibly soiled — including after contact with body fluids/excretions (then glove removal and rub).",
 o:["Equipment in direct client contact is cleaned/disinfected between clients — hand rub protects hands, not equipment surfaces.",
 "Hand hygiene IS required between body sites, contaminated to clean — the rub should be used, not avoided.",
 "Alcohol-based rub is appropriate for neutropenia precautions (it protects the client); soap-and-water is reserved for C. difficile.",
 "Correct — with no visible soiling, the rub is the preferred hand hygiene method after excretion contact."],
 s:"Rub rules: use it for all moments unless hands are visibly dirty, after C. difficile (ineffective — use soap), or before eating/after restroom. Gloves never replace hygiene."},
 ref:"Demo practice set · item 101"},

/* ── Item 102 ── */
{id:"DEMO-102", t:"single", cn:"RRP", sys:"INF", topic:"Mononucleosis · assessment", d:1, b:-0.25, cj:"recognize", tags:["assessment","infection"],
 stem:"The nurse is assessing a client with suspected mononucleosis. Which of the following findings would support a diagnosis of mononucleosis?",
 opts:["polyarthralgia","costovertebral pain","cervical lymphadenopathy","left lower quadrant (LLQ) tenderness"],
 ans:2,
 rat:{c:"Epstein-Barr virus mononucleosis presents with profound fatigue, fever, pharyngitis, and marked CERVICAL lymphadenopathy (often posterior chain), plus splenomegaly.",
 o:["Polyarthralgia suggests rheumatologic disease (lupus, RA) — not mono.",
 "Costovertebral angle pain points to pyelonephritis — not mono.",
 "Correct — cervical lymphadenopathy with fatigue/sore throat is the classic mono triad.",
 "LLQ tenderness suggests diverticulitis — mono splenomegaly is LEFT UPPER quadrant."],
 s:"Mono = tired + throat + nodes (cervical) + spleen (LUQ, avoid contact sports). Arthritis, kidney-angle pain, and LLQ pain belong to other diseases."},
 ref:"Demo practice set · item 102"},

/* ── Item 103 ── */
{id:"DEMO-103", t:"single", cn:"MOC", sys:"MSK", topic:"Delegation · UAP assignments", d:2, b:0.45, cj:"generate", tags:["delegation"],
 stem:"The nurse and unlicensed assistive personnel (UAP) are caring for assigned clients. It would be most appropriate for the nurse to assign UAP to",
 opts:["apply a continuous passive motion (CPM) device to the affected extremity of a client who had a total knee replacement","change the bed linens for a client who was admitted 1 hour ago following a closed-head injury and is comatose","reposition a client with hydrocephalus who has a headache and is vomiting","place in the prone position a client who had an above-the-knee amputation (AKA) 1 day ago"],
 ans:0,
 rat:{c:"Applying a CPM device is a routine, protocolized task on a stable postoperative client — appropriate for UAP after the nurse validates setting/position.",
 o:["Correct — mechanical, standardized care for a stable client fits the UAP scope.",
 "A comatose, fresh closed-head injury is unstable — linens may be done, but the client requires RN proximity; of the options this is not the “most appropriate” UAP task.",
 "Repositioning a client with headache and vomiting (↑ICP risk) requires nursing assessment — not UAP.",
 "Post-amputation positioning (prone for hip extension) needs assessment of tolerance, drainage, and pain — an RN task."],
 s:"UAP-safe tasks look like: ambulate stable clients, CPM device, feed stable clients, routine hygiene. Anything with “comatose,” “vomiting,” “fresh injury,” or assessment language stays with the RN."},
 ref:"Demo practice set · item 103"},

/* ── Item 104 ── */
{id:"DEMO-104", t:"single", cn:"PSY", sys:"PSYCH", topic:"Group therapy · managing disruption", d:2, b:0.5, cj:"act", tags:["psych","communication"],
 stem:"The nurse in the inpatient psychiatric unit is leading a support group for clients. It would be a priority for the nurse to intervene if the client with",
 opts:["bipolar I disorder is experiencing a manic episode, is moving the legs, and is looking around the room restlessly","borderline personality disorder is saying that another group member is too disturbed to be attending the session","major depressive disorder is sitting quietly with the eyes downcast","schizophrenia is rocking in place and copying the gestures of another client in the group"],
 ans:1,
 rat:{c:"Publicly disqualifying another member from the group attacks the safety and cohesion of the group itself — the leader must intervene to protect members and re-establish norms.",
 o:["Restless movement in mania is expected; redirect gently, but it is not the priority intervention trigger.",
 "Correct — devaluing/excluding another member violates group norms and must be addressed immediately for group safety.",
 "A withdrawn, quiet posture in depression is expected presentation — gently include without force.",
 "Rocking and mimicking in schizophrenia is expected behavior; monitor without humiliating the client."],
 s:"In group therapy, prioritize behaviors that THREATEN OTHER MEMBERS or group cohesion (devaluation, threats, secrets) over odd-but-contained self-stimulating behaviors."},
 ref:"Demo practice set · item 104"},

/* ── Item 105 ── */
{id:"DEMO-105", t:"single", cn:"MOC", sys:"PSYCH", topic:"Client rights · staff coaching", d:2, b:0.45, cj:"act", tags:["legal","communication"],
 stem:"The nurse has observed a staff member tell a client with bipolar disorder that there will be consequences for making negative comments about conditions in the facility. When the nurse meets privately with the staff member, which of the following statements would be most appropriate for the nurse to make to the staff member?",
 opts:["“Threatening a client can result in the immediate dismissal of a staff member.”","“Staff members who have difficulty with control issues often seek power over clients.”","“Clients have a right to provide feedback about services without fear of punishment.”","“Staff should set limits with clients in a nonjudgmental manner.”"],
 ans:2,
 rat:{c:"The corrective teaching point is the client’s RIGHT to give feedback free of retaliation — stating it plainly reframes the staff member’s behavior without attacking them.",
 o:["Leading with punishment/HR consequences makes it about the staff member’s job, not the client’s rights.",
 "Psychoanalyzing the staff member (“control issues”) is accusatory and unprofessional in feedback.",
 "Correct — clients may voice complaints without fear of consequences; retaliation is never acceptable.",
 "Limit-setting language applies to managing client behavior — here the problem is the STAFF response to feedback."],
 s:"Feedback to staff: name the principle (client rights), not the person’s character; keep it private, specific, and corrective."},
 ref:"Demo practice set · item 105"},

/* ── Item 106 ── */
{id:"DEMO-106", t:"single", cn:"MOC", sys:"CV", topic:"Prioritization · pulsus paradoxus", d:3, b:0.9, cj:"prioritize", tags:["priority","assessment"],
 stem:"The nurse has been made aware of the following client situations. The nurse should first assess the client",
 opts:["with chronic obstructive pulmonary disease (COPD) who is using pursed-lip breathing after ambulating in the hallway","with pericarditis who has a systolic blood pressure that is 20 mm Hg higher during expiration than during inspiration","who had a total abdominal hysterectomy (TAH) 12 hours ago and has saturated 1 perineal pad in the past 5 hours","who has Guillain-Barré syndrome and has had an increase in the vital capacity over the past 4 hours"],
 ans:1,
 rat:{c:"A 20 mm Hg inspiratory drop in systolic pressure is pulsus paradoxus — with pericarditis it signals possible cardiac tamponade (also: muffled heart sounds, jugular distention), an emergency.",
 o:["Pursed-lip breathing after activity is a taught COPD technique working as designed.",
 "Correct — pulsus paradoxus ≥ 10–20 mm Hg with pericarditis suggests tamponade: assess immediately.",
 "One saturated pad in 5 hours after TAH is below expected bleeding — reassuring.",
 "INCREASING vital capacity in Guillain-Barré means improving respiratory muscle strength — a good trend."],
 s:"Pericarditis + big pulsus paradoxus + distended neck veins + muffled sounds = tamponade. Rising vital capacity in GBS is the trend you WANT."},
 ref:"Demo practice set · item 106"},

/* ── Item 107 ── */
{id:"DEMO-107", t:"single", cn:"PSY", sys:"PSYCH", topic:"Borderline personality · limit setting", d:2, b:0.5, cj:"act", tags:["psych","communication"],
 stem:"The nurse in the psychiatric unit is administering medications when a client with a borderline personality disorder approaches and asks to talk. The nurse suggests having a talk in 1 hour. The client shouts, “I’ll wait, but you will be sorry!” and then picks up a pitcher of water and throws it onto the floor. Which of the following actions should the nurse take?",
 opts:["Offer to listen to the client while continuing to administer the medications.","Suggest that the client take a p.r.n. prescribed medication for agitation.","Ask another nurse to finish giving the medications, and talk with the client.","Request assistance from several nearby staff members with controlling the client’s behavior."],
 ans:2,
 rat:{c:"The nurse keeps the agreed commitment safely: hand off the medication task and talk with the client now — honoring limits while providing the attention the behavior is demanding.",
 o:["Dividing attention shortchanges both tasks and models broken boundaries.",
 "PRN medication is for agitation the client cannot control — this is a boundary-testing behavior, not medication-seeking distress.",
 "Correct — hand off the task and keep the promised talk; consistent, calm follow-through is the intervention.",
 "Calling for physical control escalates a verbal/throwing incident that does not require restraint — least restrictive first."],
 s:"Borderline playbook: consistent limits + follow-through, don’t abandon or punish, address the behavior calmly, reserve PRN/restraints for genuine safety threats."},
 ref:"Demo practice set · item 107"},

/* ── Item 108 ── */
{id:"DEMO-108", t:"single", cn:"PHA", sys:"INF", topic:"HIV · supplement safety", d:2, b:0.4, cj:"evaluate", tags:["infection","medication","teaching"],
 stem:"The nurse is talking with a client who has a positive laboratory test result for human immunodeficiency virus (HIV) infection. Which of the following statements by the client would require follow-up?",
 opts:["“I try to eat a well-balanced diet.”","“I avoid crowds when I go outside the house.”","“I am taking a vitamin C tablet daily to help prevent infections.”","“I take echinacea every day to help improve my immune system.”"],
 ans:3,
 rat:{c:"Immune-stimulating supplements like echinacea can interfere with HIV treatment and are not recommended — daily unregulated immune boosters warrant follow-up.",
 o:["A well-balanced diet supports health — good.",
 "Avoiding crowds reduces infection exposure — reasonable self-care.",
 "A daily vitamin C tablet is generally benign — acceptable.",
 "Requires follow-up — echinacea (an immune stimulant) may interact with antiretroviral therapy and is not endorsed; all supplements should be cleared with the provider."],
 s:"HIV + “herbal immune booster” = follow-up. Unregulated supplements risk drug interactions with antiretrovirals; check everything with the provider."},
 ref:"Demo practice set · item 108"},

/* ── Item 109 ── */
{id:"DEMO-109", t:"multi", cn:"MOC", sys:"INF", topic:"Informed consent · principles", d:3, b:0.85, cj:"generate", tags:["legal","teaching"],
 stem:"The nurse is planning a staff education program about informed consent. Which of the following information should the nurse include? Select all that apply.",
 opts:["“An individual designated by a power of attorney for health care can provide informed consent despite the competency of the client.”","“The nurse has a duty to insist that the client repeat what has been said about a procedure for which consent is necessary.”","“The primary health care provider must disclose the risks if the client declines a recommended procedure.”","“The client should sign the consent form prior to receiving prescribed opioids.”","“Informed consent is not needed for emergency procedures that are in the client’s best interest.”"],
 ans:[1,3,4],
 rat:{c:"Valid consent requires capacity, disclosure, voluntariness, and comprehension — the nurse verifies (and can ask the client to restate) understanding; signing precedes sedation; and true emergencies allow treatment without consent.",
 o:["A health care POA speaks only when the client CANNOT speak for themselves — a competent client’s consent rules.",
 "Correct — verifying understanding (having the client restate the procedure in their own words) is a nursing responsibility in the consent process.",
 "Risk/benefit disclosure happens when OBTAINING consent, not as a penalty for declining — the client may refuse outright.",
 "Correct — opioids/sedation impair capacity: sign first, medicate after.",
 "Correct — implied consent covers life-saving emergency care when consent is unobtainable."],
 s:"Consent nuances tested here: POA yields to a competent client; teach-back verifies understanding; sedation invalidates signing; refusal is a right; emergencies are the exception."},
 ref:"Demo practice set · item 109"},

/* ── Item 110 ── */
{id:"DEMO-110", t:"single", cn:"PHA", sys:"INF", topic:"IV fluid error · first action", d:2, b:0.5, cj:"act", tags:["iv-therapy","safety","priority"],
 stem:"The nurse is caring for a client who has a prescription for an intravenous infusion of 0.45% sodium chloride (half-strength saline). The nurse notes the client is receiving 5% dextrose in water. Which of the following actions should the nurse take first?",
 opts:["Change the intravenous fluid to the prescribed fluid.","Notify the primary health care provider.","Complete an incident report.","Assess the client."],
 ans:3,
 rat:{c:"Whenever a medication/fluid error is discovered, ASSESS the client first — client safety precedes fixing the tubing, notifying, or paperwork.",
 o:["Correct — assess the client first (vitals, site, glucose effects), then correct the error.",
 "The provider is notified, but after you know how the client is.",
 "The incident report comes later — documentation never precedes client assessment.",
 "Assessment first — the client outranks the correction process."],
 s:"Error-response order: ASSESS the client → fix/intervene → notify the provider → document/incident report. Every time."},
 ref:"Demo practice set · item 110"},

/* ── Item 111 ── */
{id:"DEMO-111", t:"single", cn:"PAA", sys:"REPI", topic:"Umbilical cord prolapse · emergency", d:1, b:-0.15, cj:"act", tags:["emergency","maternity"],
 stem:"The nurse is caring for a client in the first stage of labor and observes that a segment of the umbilical cord is visible in the vaginal opening after rupture of the client’s amniotic membranes. Which of the following actions should the nurse take?",
 opts:["Instruct the client to lie on her left side.","Attempt to place the umbilical cord back into the uterus.","Assist the client into a knee-chest position.","Administer an intravenous tocolytic agent."],
 ans:2,
 rat:{c:"Visible cord after membrane rupture is cord prolapse: relieve pressure off the cord NOW with knee-chest (or Trendelenburg) position, call for help, and prepare for immediate cesarean birth.",
 o:["Left side-lying does not lift the presenting part off the cord.",
 "Never reinsert the cord — lift the presenting part off the cord with a gloved hand and position the mother.",
 "Correct — knee-chest (or head-down Trendelenburg) uses gravity to keep the presenting part off the cord until delivery.",
 "Tocolytics may be ordered later by the provider — positioning is the immediate nursing action."],
 s:"Cord prolapse drill: knee-chest/Trendelenburg + call for help + lift presenting part + continuous fetal monitoring + prepare for STAT cesarean."},
 ref:"Demo practice set · item 111"},

/* ── Item 113 ── */
{id:"DEMO-113", t:"single", cn:"PHA", sys:"REN", topic:"Aminoglycosides · preadministration labs", d:1, b:-0.25, cj:"act", tags:["medication","renal"],
 stem:"The nurse is preparing to administer an aminoglycoside. Which of the following laboratory test results should the nurse review before administering the medication?",
 opts:["serum electrolyte level and serum uric acid level","hemoglobin (Hgb) and white blood cell (WBC) count","serum ammonia level and serum glucose level","blood urea nitrogen (BUN) and serum creatinine"],
 ans:3,
 rat:{c:"Aminoglycosides (gentamicin, tobramycin, amikacin) are nephrotoxic and ototoxic — renal function (BUN/creatinine) governs dosing and safety before every administration.",
 o:["Electrolytes/uric acid do not gate aminoglycoside dosing.",
 "Hgb/WBC reflect anemia/infection status, not drug clearance.",
 "Ammonia/glucose relate to hepatic and metabolic function — not this drug class.",
 "Correct — BUN and creatinine verify kidney function before a nephrotoxic dose (peak/trough levels are also monitored)."],
 s:"Aminoglycoside = “gotta check the kidneys AND the ears”: BUN/creatinine before, peak/trough during, report tinnitus/ototoxicity and decreased urine output."},
 ref:"Demo practice set · item 113"},

/* ── Item 114 ── */
{id:"DEMO-114", t:"multi", cn:"RRP", sys:"GI", topic:"ERCP · preprocedure preparation", d:2, b:0.45, cj:"generate", tags:["diagnostics","safety","teaching"],
 stem:"The nurse is talking with a client who is scheduled for endoscopic retrograde cholangiopancreatography (ERCP) in 2 hours in the outpatient department. Which of the following questions would be important for the nurse to ask? Select all that apply.",
 opts:["“How will you be getting home after the procedure?”","“Do you have access to a thermometer after you leave here?”","“What allergies do you have?”","“Are you wearing dentures?”","“Do you have external hemorrhoids?”"],
 ans:[0,2,3],
 rat:{c:"ERCP uses sedation and contrast: arrange a responsible escort, screen allergies (contrast, latex, sedation), and ask about dentures/removable appliances removed before endoscopy.",
 o:["Correct — sedation mandates a responsible adult to drive the client home.",
 "A post-discharge thermometer is helpful after some procedures, but it is not a core pre-ERCP question.",
 "Correct — contrast and sedation allergies change the plan (and anticoagulant history matters).",
 "Correct — dentures and removable dental appliances come out before an upper endoscope passes.",
 "External hemorrhoids are irrelevant to an upper GI/endoscopic procedure."],
 s:"Pre-ERCP checklist: NPO status, allergies (contrast/sedation/latex), anticoagulants, dentures out, sedation consent, escort home. Think “sedation + contrast + scope.”"},
 ref:"Demo practice set · item 114"},

/* ── Item 115 ── */
{id:"DEMO-115", t:"single", cn:"RRP", sys:"CV", topic:"Cardiac catheterization · complications", d:2, b:0.5, cj:"recognize", tags:["assessment","postoperative"],
 stem:"The nurse is assessing a client who had cardiac catheterization 2 hours ago. Which of the following findings would require immediate follow-up?",
 opts:["blood pressure 104/70 mm Hg","1+ pedal pulse of the affected extremity","heart rate 98/min","urine output of 100 mL for the past 2 hours"],
 ans:1,
 rat:{c:"A diminished (1+) pedal pulse on the catheterized limb signals compromised arterial flow — hematoma, thrombus, or dissection can cost the limb; immediate follow-up.",
 o:["BP 104/70 is acceptable post-procedure.",
 "Correct — decreased pulse quality on the accessed extremity = possible occlusion: act now (compare bilaterally, notify).",
 "HR 98/min is within normal range.",
 "50 mL/hr urine output is adequate (and contrast is diuresed)."],
 s:"Post-catheter checks: puncture-site bleeding/hematoma, distal pulses and color/warmth (both limbs compared), neuro checks, hydration. A weaker pulse = vascular emergency until proven otherwise."},
 ref:"Demo practice set · item 115"},

/* ── Item 116 ── */
{id:"DEMO-116", t:"single", cn:"HPM", sys:"NEURO", topic:"Bacterial conjunctivitis · parent teaching", d:1, b:-0.25, cj:"evaluate", tags:["pediatrics","teaching","infection-control"],
 stem:"The nurse has taught the parent of a 9-year-old child who has been newly diagnosed with bacterial conjunctivitis. Which of the following statements by the parent would indicate a correct understanding of the teaching?",
 opts:["“The infection produces profuse watery discharge.”","“I should clean my child’s eyelids and eyelashes with soap and water prior to instilling the medication.”","“My child’s eyes may be sensitive to light until the infection resolves.”","“The prescribed corticosteroid eyedrops should be used for 1 week.”"],
 ans:2,
 rat:{c:"Bacterial conjunctivitis causes purulent discharge and photophobia; sensitivity to light persists while inflamed — the correct expectation to teach.",
 o:["Profuse WATERY discharge describes viral/allergic conjunctivitis; bacterial discharge is purulent (yellow-green).",
 "Cleanse with warm water or sterile saline and wipe inner to outer canthus — plain soap is not the taught method.",
 "Correct — photophobia accompanies the inflammation and resolves with treatment.",
 "Bacterial conjunctivitis is treated with ANTIBIOTIC drops (after 24 h on drops, child may return to school); corticosteroid drops are not the routine prescription."],
 s:"Pinkeye cheat sheet: bacterial = purulent, antibiotic drops, inner-to-outer cleansing; viral = watery, supportive care; both = hand hygiene, no shared towels."},
 ref:"Demo practice set · item 116"},

/* ── Item 117 ── */
{id:"DEMO-117", t:"single", cn:"PHA", sys:"ENDO", topic:"Insulin pump · client teaching", d:2, b:0.45, cj:"evaluate", tags:["diabetes","medication","teaching"],
 stem:"The nurse is talking with a client who has diabetes mellitus (type 1) and is receiving insulin via an infusion pump. Which of the following statements by the client would require follow-up?",
 opts:["“I need a bolus dose of insulin prior to a meal.”","“I should refill the pump with short-duration insulin.”","“I can decrease serum glucose monitoring to twice daily.”","“I will change the infusion needle every 2 to 3 days.”"],
 ans:2,
 rat:{c:"Pump therapy demands FREQUENT glucose monitoring (typically at least 4 times daily plus CGM) to catch infusion failures — cutting checks to twice daily is unsafe.",
 o:["A premeal bolus (via pump) matches carbohydrate intake — correct.",
 "Pumps use rapid/short-acting insulin only (no long-acting) — correct.",
 "Correct — requires follow-up: pump users monitor glucose frequently; twice daily is far too little to detect failures.",
 "Changing the infusion set/needle every 2 to 3 days prevents site infection and absorption problems — correct."],
 s:"Insulin pump = rapid-acting insulin only + frequent monitoring. The pump can fail silently; glucose checks are the safety net."},
 ref:"Demo practice set · item 117"},

/* ── Item 118 ── */
{id:"DEMO-118", t:"multi", cn:"MOC", sys:"MSK", topic:"Surgical consent · preoperative checks", d:2, b:0.55, cj:"evaluate", tags:["legal","safety","surgery"],
 stem:"The nurse is caring for a client who is scheduled for a spinal fusion in 1 hour. Which of the following situations would require follow-up? Select all that apply.",
 opts:["The nurse notes that the client signed the consent form 1 week ago.","The nurse determines that the last analgesia the client received was yesterday afternoon.","The client states, “I need to find out why the surgery is needed before I sign the consent form.”","The nurse administers the prescribed preoperative sedation after the client signs the consent form.","The client states, “I am afraid to sign the consent form because I know I am going to die during the surgery.”","The client states, “The surgery may result in some paralysis, but the resolution of the pain is worth the risk to me.”"],
 ans:[0,2,4],
 rat:{c:"Consent problems: a stale signature (signed a week ago for today’s surgery needs re-verification), an unanswered “why do I need this” (not informed), and a hopeless death conviction (reflects unresolved fear/distorted thinking — explore before sedation).",
 o:["Correct — a consent signed that far ahead should be revisited: confirm the client remains informed and willing (or re-consent per policy).",
 "Analgesia timing is routine perioperative information — not a consent problem.",
 "Correct — the client lacks understanding of the procedure: notify the provider so informed consent can truly occur.",
 "Signing BEFORE sedation is exactly the correct sequence — no follow-up needed.",
 "Correct — an expressed certainty of dying deserves exploration and support before the client is sedated and proceeds.",
 "Weighing risks against benefits and choosing surgery is informed acceptance — no follow-up needed."],
 s:"Consent red flags: don’t understand it, signed too far in advance (or under sedation), expresses hopelessness or coercion. Risk-acceptance = informed consent working."},
 ref:"Demo practice set · item 118"},

/* ── Item 119 ── */
{id:"DEMO-119", t:"single", cn:"MOC", sys:"PSYCH", topic:"Psychiatric unit · client selection", d:2, b:0.6, cj:"generate", tags:["psych","safety","delegation"],
 stem:"The charge nurse must transfer a client from a locked psychiatric unit to an unlocked unit in order to make a bed available. The charge nurse should recommend for transfer the client with",
 opts:["depression who has suddenly become more animated and involved in unit activities","bipolar I disorder who is experiencing a manic episode, is disrobing, and is laughing with other clients","schizophrenia who is withdrawn and requires assistance with activities of daily living (ADL)","dementia who is delusional about being poisoned by staff members"],
 ans:2,
 rat:{c:"The withdrawn client with schizophrenia needing ADL help is predictable and safe on an unlocked unit. The others carry elopement, escalation, or suicide risks.",
 o:["SUDDEN animation after depression can signal a resolved ambivalence about suicide (energy returned before hope) — suicide risk, keep locked/observed.",
 "Acute mania with disrobing needs a secure, contained environment.",
 "Correct — withdrawn, nonviolent, assistance-level care transfers safely to an unlocked setting.",
 "Active paranoia about being poisoned predicts refusal of care and escalation — unsafe on an unlocked unit."],
 s:"Unlocked-unit suitability = low elopement + low suicide + low violence risk. Watch for the “suddenly happy” depressed client — energy before hope is lethal."},
 ref:"Demo practice set · item 119"},

/* ── Item 121 ── */
{id:"DEMO-121", t:"single", cn:"PAA", sys:"RESP", topic:"Trauma · airway threat", d:1, b:-0.2, cj:"prioritize", tags:["emergency","priority","trauma"],
 stem:"The nurse in the emergency department (ED) is assessing a client with multiple injuries that occurred as a result of a motor vehicle collision. Which of the following findings should receive highest priority?",
 opts:["avulsion injury of the left index finger","deep laceration on the right forearm with blood oozing from the surface","hematoma on the left side of the neck","open fracture of the right tibia and fibula"],
 ans:2,
 rat:{c:"A neck hematoma can expand and compress or shift the airway (and major vessels) — an airway threat always outranks limb injuries.",
 o:["An avulsed finger is limb-threatening, not life-threatening.",
 "A slow-oozing forearm laceration is controlled with pressure — not the priority.",
 "Correct — a hematoma on the neck threatens the AIRWAY: monitor closely and anticipate emergency airway management.",
 "An open tibia/fibula fracture is serious limb trauma — after ABCs."],
 s:"Trauma triage = ABC: anything near the airway (neck hematoma, expanding neck wound) wins over even dramatic-looking limb injuries."},
 ref:"Demo practice set · item 121"},

/* ── Item 122 ── */
{id:"DEMO-122", t:"single", cn:"MOC", sys:"CV", topic:"Prioritization · aneurysm leakage", d:2, b:0.55, cj:"prioritize", tags:["priority","assessment"],
 stem:"The nurse has received information about assigned clients. The nurse should first assess the client",
 opts:["with multiple sclerosis (MS) who had an indwelling urethral catheter removed 5 hours ago and has not been able to urinate","with an abdominal aortic aneurysm (AAA) who reports recent onset of low back pain","who had coronary artery bypass graft (CABG) surgery 2 days ago and reports sternal pain when coughing","who has bacterial pneumonia and is requesting a cough suppressant"],
 ans:1,
 rat:{c:"New back pain in a client with a known AAA is the classic sign of expansion or leakage — a surgical emergency; assess first.",
 o:["Post-catheter urinary retention needs a bladder scan within the hour — uncomfortable, not lethal.",
 "Correct — new low back pain with AAA = possible rupture: immediate assessment and provider notification.",
 "Sternal pain when coughing 2 days after CABG is common (note: report “popping”/separation) — monitor.",
 "A cough-suppressant request is a comfort need, especially as productive coughs should not be suppressed in pneumonia."],
 s:"AAA + new back/flank/abdominal pain = leaking until proven otherwise. That beats retention, expected incisional pain, and med requests."},
 ref:"Demo practice set · item 122"},

/* ── Item 123 ── */
{id:"DEMO-123", t:"single", cn:"MOC", sys:"RESP", topic:"Documentation · legal defense", d:2, b:0.5, cj:"evaluate", tags:["documentation","legal","nutrition"],
 stem:"The nurse who cared for a client with chronic obstructive pulmonary disease (COPD) who lost more than 10% of ideal body weight has been named in a lawsuit charging negligence. Which of the following entries in the client’s medical record would help refute the charge of negligence?",
 opts:["The client has been instructed to eat 3 large meals daily.","The client has been encouraged to maintain a high-calorie, high-protein diet.","The client has been encouraged to drink fluids with meals to promote digestion.","The client has been instructed to exercise 30 minutes before eating to improve appetite."],
 ans:1,
 rat:{c:"The record shows appropriate standard-of-care nutrition intervention: high-calorie, high-protein intake for a malnourished COPD client — exactly what the evidence-based intervention looks like.",
 o:["Three LARGE meals worsen dyspnea and early satiety in COPD — small frequent meals are taught; this entry would not defend care.",
 "Correct — documented high-calorie, high-protein encouragement reflects correct COPD nutrition care and defends the nurse.",
 "Fluids WITH meals cause early satiety — drink between meals instead; the entry documents substandard teaching.",
 "Exercising before meals wastes calories and suppresses appetite — not defensible advice."],
 s:"In malpractice questions, pick the entry matching the textbook intervention. COPD weight loss: small frequent high-calorie/high-protein meals, fluids between meals, rest before eating."},
 ref:"Demo practice set · item 123"},

/* ── Item 124 ── */
{id:"DEMO-124", t:"single", cn:"MOC", sys:"INF", topic:"Documentation · IV therapy", d:2, b:0.5, cj:"evaluate", tags:["documentation","iv-therapy"],
 stem:"The nurse is documenting care for a client who had a peripheral VAD placed 10 minutes ago. Which of the following would be the best example of correct documentation for the nurse to include in the client’s medical record?",
 opts:["22-gauge catheter inserted into the right hand.","Secured the site with paper tape to avoid skin tears.","Infusion started slowly due to reports of coolness at the site.","Labeled site, tubing, and intravenous fluid bag."],
 ans:0,
 rat:{c:"A complete procedure note records the concrete facts of the insertion: device gauge and anatomic site (plus time, attempts, dressing, tolerance, and flushing).",
 o:["Correct — documents the specifics of the device (gauge) and location (right hand) — objective procedure data.",
 "Tape choice alone is an intervention fragment, not the procedure record.",
 "Infusing slowly for coolness suggests infiltration — that documents a problem, not the insertion.",
 "Labeling is a required ACTION, but it is not the insertion documentation itself."],
 s:"Good procedure notes answer: what (gauge/device), where (site), when, how the client tolerated it, and the plan. Objective beats vague activity lists."},
 ref:"Demo practice set · item 124"},

/* ── Item 125 ── */
{id:"DEMO-125", t:"single", cn:"RRP", sys:"INF", topic:"Monitoring · lab-test matching", d:2, b:0.45, cj:"evaluate", tags:["assessment","diagnostics"],
 stem:"The nurse is caring for assigned clients. It would be most important for the nurse to monitor",
 opts:["serum lipase levels for the client with hypercholesterolemia","arterial blood gas (ABG) results for the client who has an acid-base imbalance","serum glucose levels for the client with diabetes insipidus (DI)","adrenocorticotropic hormone (ACTH) levels for the client who has a fluid imbalance"],
 ans:1,
 rat:{c:"ABGs directly quantify the acid-base disturbance and guide treatment — the matched, essential monitoring pair.",
 o:["Hypercholesterolemism is monitored with a lipid panel — lipase tracks PANCREATITIS.",
 "Correct — ABGs are the definitive monitoring tool for acid-base imbalance.",
 "Diabetes insipidus is a water problem: monitor urine output/specific gravity and SERUM SODIUM (glucose is diabetes mellitus).",
 "Fluid imbalance is monitored with intake/output, weight, and electrolytes — ACTH is an adrenal-axis test."],
 s:"Match the test to the disease: lipase = pancreatitis; glucose = DM; sodium/UOP = DI; ACTH/cortisol = adrenal disease; ABG = acid-base/oxygenation."},
 ref:"Demo practice set · item 125"},

/* ── Item 126 ── */
{id:"DEMO-126", t:"single", cn:"MOC", sys:"INF", topic:"Conflict resolution · collaboration", d:2, b:0.45, cj:"evaluate", tags:["leadership"],
 stem:"The nurse is planning a staff education program about collaborative conflict resolution strategies. Which of the following would best describe implementation of a collaborative conflict resolution strategy?",
 opts:["“A staff nurse is working with the nurse manager and offering suggestions about an upcoming new procedure.”","“The clinical nurse leader is flattered by being asked to help create a clinical ladder for nursing staff members.”","“The charge nurse is working with staff nurses and the nurse manager to develop shared goals and a plan for the new staffing format.”","“A new nurse has offered to work on a holiday in exchange for having the following weekend off.”"],
 ans:2,
 rat:{c:"Collaboration means all stakeholders jointly define SHARED goals and build the plan together — exactly what the charge nurse, staff nurses, and manager are doing.",
 o:["Offering suggestions upward is participation, not joint goal-setting.",
 "Being flattered is a personal/emotional response — not a conflict-resolution strategy.",
 "Correct — shared goals + joint planning among all parties = collaboration.",
 "A swap agreement is negotiation/bargaining, not collaboration."],
 s:"Collaboration = everyone at the table co-creating shared goals. Distinguish from negotiation (trade-offs), accommodation (yielding), and smooth suggestion-making."},
 ref:"Demo practice set · item 126"},

/* ── Item 127 ── */
{id:"DEMO-127", t:"single", cn:"HPM", sys:"INF", topic:"Tuberculosis · public health follow-up", d:2, b:0.45, cj:"analyze", tags:["infection","community"],
 stem:"The nurse is caring for a client who lives with a spouse and 2 adolescent children. The client has been admitted to a hospital for treatment of active pulmonary tuberculosis (TB). The local health department has been notified about the client’s diagnosis. The nurse should recognize that after this notification the local health department will",
 opts:["schedule periodic examinations of the client’s chest and sputum","contact the client’s family to arrange for family members to be examined","immunize those persons with whom the client has been in contact","isolate members of the client’s immediate family at home until diagnostic studies rule out TB"],
 ans:1,
 rat:{c:"Public health’s core TB response is contact investigation: reaching out to household/close contacts and arranging testing (skin/blood test, then evaluation).",
 o:["Following the hospitalized client’s own disease course is the hospital team’s job.",
 "Correct — the health department conducts contact tracing and arranges examination/testing of family and close contacts.",
 "There is no routine immunization for contacts (BCG is not used in the U.S. for this purpose); testing and treating latent infection is the approach.",
 "Home quarantine of family members is not the standard response — testing and evaluation are."],
 s:"Health department TB playbook: identify contacts → test them → evaluate/treat latent infection → ensure the index case completes therapy (DOT)."},
 ref:"Demo practice set · item 127"},

/* ── Item 128 ── */
{id:"DEMO-128", t:"single", cn:"MOC", sys:"INF", topic:"Disaster triage · priority", d:2, b:0.55, cj:"prioritize", tags:["emergency","priority"],
 stem:"The nurse is participating in a community-based disaster drill. The nurse should give priority for treatment to a",
 opts:["2-year-old client with a bleeding scalp laceration and briskly reactive pupils","15-year-old client who is restless and has a distended, firm abdomen","30-year-old client who has a leg wound exposing the femur, a blood pressure of 120/76 mm Hg, and a pulse of 90","60-year-old client with heart failure whose pulse oximetry reading is 92% on room air and whose respirations are 26"],
 ans:1,
 rat:{c:"Restlessness with a distended, firm abdomen suggests internal hemorrhage — unstable and salvageable: treat first. The others are stable or non-salvageable-category presentations.",
 o:["A scalp laceration bleeds impressively but is a controlled external bleed with normal neuro status — can wait with pressure applied.",
 "Correct — firm distended abdomen + restlessness = intra-abdominal bleeding: immediate intervention (disaster “immediate/red” category).",
 "An exposed femur wound with NORMAL vitals is urgent limb care but hemodynamically stable.",
 "92% saturation with compensated breathing in a heart failure client is serious but not the immediate life-threat."],
 s:"Disaster triage (START): fix airway, breathing, perfusion. Internal bleeding (distended abdomen, falling BP, restlessness) outranks external bleeds and chronic exacerbations."},
 ref:"Demo practice set · item 128"},

/* ── Item 129 ── */
{id:"DEMO-129", t:"single", cn:"MOC", sys:"MSK", topic:"Telephone triage · pediatric casts", d:2, b:0.5, cj:"prioritize", tags:["priority","pediatrics","safety"],
 stem:"The nurse in a community-based setting has received the following telephone messages. The nurse should first return the telephone call to the parent of a",
 opts:["3-year-old child who sustained a concussion and was irritable when awakened every 2 hours during the night","4-year-old child with impetigo contagiosa who has eruptions spreading around the mouth and nose that are draining thin yellow fluid","5-year-old child with Ewing sarcoma who is receiving external radiation and the irradiated area appears reddened","6-year-old child with a right long-leg cast whose toes on the affected extremity are swollen and cool to the touch"],
 ans:3,
 rat:{c:"Swollen, COOL toes in a cast signal compromised circulation — compartment syndrome until proven otherwise; this call gets returned first.",
 o:["Nightly irritability with successful arousal is expected after concussion (wake q2h is the instruction) — call back soon.",
 "Spreading impetigo needs a visit/treatment but is not limb-threatening.",
 "Radiation erythema is an expected, monitored skin reaction — routine guidance call.",
 "Correct — cool, swollen toes = neurovascular compromise: instruct immediate cast evaluation/ED now."],
 s:"Cast calls: the 6 Ps (pain, pallor, paresthesia, paralysis, pressure, poikilothermia/coolness) = emergency. Everything else on this list can wait hours."},
 ref:"Demo practice set · item 129"},

/* ── Item 130 ── */
{id:"DEMO-130", t:"single", cn:"PHA", sys:"HEME", topic:"Clopidogrel · client teaching", d:1, b:-0.2, cj:"generate", tags:["medication","teaching"],
 stem:"The nurse is teaching a client who is receiving newly prescribed clopidogrel. Which of the following information should the nurse include?",
 opts:["“Notify your primary health care provider if you experience unusual bruising.”","“Avoid taking over-the-counter (OTC) medications containing acetaminophen.”","“Avoid driving your car for a short time until your response to the medication is known.”","“Have a blood specimen obtained every 3 months to check your serum albumin level.”"],
 ans:0,
 rat:{c:"Clopidogrel inhibits platelet function and raises bleeding risk — unusual bruising or bleeding must be reported for prompt evaluation.",
 o:["Correct — unexpected bruising/bleeding (gums, urine, stool) signals platelet inhibition problems; report it.",
 "The OTC warning for antiplatelet therapy is NSAIDs/aspirin (added bleeding risk) — acetaminophen is the acceptable analgesic.",
 "Driving restrictions apply to drugs causing sedation, not antiplatelet agents.",
 "Albumin levels have nothing to do with clopidogrel — no such monitoring is required."],
 s:"Antiplatelet teaching: report unusual bleeding/bruising, avoid NSAIDs, use soft toothbrush/electric razor, notify providers before procedures. Acetaminophen is fine."},
 ref:"Demo practice set · item 130"}

];
